    CopyStepDetails.add_member(:destination_file_location, Smithy::Schema::Shapes::ShapeRef.new(shape: InputFileLocation, location_name: 'DestinationFileLocation', traits: {"smithy.api#documentation" => "<p>Specifies the location for the file being copied. Use <code>${Transfer:UserName}</code> or <code>${Transfer:UploadDate}</code> in this field to parametrize the destination prefix by username or uploaded date.</p> <ul> <li> <p>Set the value of <code>DestinationFileLocation</code> to <code>${Transfer:UserName}</code> to copy uploaded files to an Amazon S3 bucket that is prefixed with the name of the Transfer Family user that uploaded the file.</p> </li> <li> <p>Set the value of <code>DestinationFileLocation</code> to <code>${Transfer:UploadDate}</code> to copy uploaded files to an Amazon S3 bucket that is prefixed with the date of the upload.</p> <note> <p>The system resolves <code>UploadDate</code> to a date format of <i>YYYY-MM-DD</i>, based on the date the file is uploaded in UTC.</p> </note> </li> </ul>"}))
    CopyStepDetails.add_member(:overwrite_existing, Smithy::Schema::Shapes::ShapeRef.new(shape: OverwriteExisting, location_name: 'OverwriteExisting', traits: {"smithy.api#documentation" => "<p>A flag that indicates whether to overwrite an existing file of the same name. The default is <code>FALSE</code>.</p> <p>If the workflow is processing a file that has the same name as an existing file, the behavior is as follows:</p> <ul> <li> <p>If <code>OverwriteExisting</code> is <code>TRUE</code>, the existing file is replaced with the file being processed.</p> </li> <li> <p>If <code>OverwriteExisting</code> is <code>FALSE</code>, nothing happens, and the workflow processing stops.</p> </li> </ul>"}))
    CopyStepDetails.add_member(:source_file_location, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceFileLocation, location_name: 'SourceFileLocation', traits: {"smithy.api#documentation" => "<p>Specifies which file to use as input to the workflow step: either the output from the previous step, or the originally uploaded file for the workflow.</p> <ul> <li> <p>To use the previous file as the input, enter <code>${previous.file}</code>. In this case, this workflow step uses the output file from the previous workflow step as input. This is the default value.</p> </li> <li> <p>To use the originally uploaded file location as input for this step, enter <code>${original.file}</code>.</p> </li> </ul>"}))
    CopyStepDetails.type = Types::CopyStepDetails
    CreateAccessRequest.add_member(:home_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'HomeDirectory', traits: {"smithy.api#documentation" => "<p>The landing directory (folder) for a user when they log in to the server using the client.</p> <p>A <code>HomeDirectory</code> example is <code>/bucket_name/home/mydirectory</code>.</p> <note> <p>You can use the <code>HomeDirectory</code> parameter for <code>HomeDirectoryType</code> when it is set to either <code>PATH</code> or <code>LOGICAL</code>.</p> </note>"}))
    CreateAccessRequest.add_member(:home_directory_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryType, location_name: 'HomeDirectoryType', traits: {"smithy.api#documentation" => "<p>The type of landing directory (folder) that you want your users' home directory to be when they log in to the server. If you set it to <code>PATH</code>, the user will see the absolute Amazon S3 bucket or Amazon EFS path as is in their file transfer protocol clients. If you set it to <code>LOGICAL</code>, you need to provide mappings in the <code>HomeDirectoryMappings</code> for how you want to make Amazon S3 or Amazon EFS paths visible to your users.</p> <note> <p>If <code>HomeDirectoryType</code> is <code>LOGICAL</code>, you must provide mappings, using the <code>HomeDirectoryMappings</code> parameter. If, on the other hand, <code>HomeDirectoryType</code> is <code>PATH</code>, you provide an absolute path using the <code>HomeDirectory</code> parameter. You cannot have both <code>HomeDirectory</code> and <code>HomeDirectoryMappings</code> in your template.</p> </note>"}))
    CreateAccessRequest.add_member(:home_directory_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryMappings, location_name: 'HomeDirectoryMappings', traits: {"smithy.api#documentation" => "<p>Logical directory mappings that specify what Amazon S3 or Amazon EFS paths and keys should be visible to your user and how you want to make them visible. You must specify the <code>Entry</code> and <code>Target</code> pair, where <code>Entry</code> shows how the path is made visible and <code>Target</code> is the actual Amazon S3 or Amazon EFS path. If you only specify a target, it is displayed as is. You also must ensure that your Identity and Access Management (IAM) role provides access to paths in <code>Target</code>. This value can be set only when <code>HomeDirectoryType</code> is set to <i>LOGICAL</i>.</p> <p>The following is an <code>Entry</code> and <code>Target</code> pair example.</p> <p> <code>[ { \"Entry\": \"/directory1\", \"Target\": \"/bucket_name/home/mydirectory\" } ]</code> </p> <p>In most cases, you can use this value instead of the session policy to lock down your user to the designated home directory (\"<code>chroot</code>\"). To do this, you can set <code>Entry</code> to <code>/</code> and set <code>Target</code> to the <code>HomeDirectory</code> parameter value.</p> <p>The following is an <code>Entry</code> and <code>Target</code> pair example for <code>chroot</code>.</p> <p> <code>[ { \"Entry\": \"/\", \"Target\": \"/bucket_name/home/mydirectory\" } ]</code> </p>"}))
    CreateAccessRequest.add_member(:policy, Smithy::Schema::Shapes::ShapeRef.new(shape: Policy, location_name: 'Policy', traits: {"smithy.api#documentation" => "<p>A session policy for your user so that you can use the same Identity and Access Management (IAM) role across multiple users. This policy scopes down a user's access to portions of their Amazon S3 bucket. Variables that you can use inside this policy include <code>${Transfer:UserName}</code>, <code>${Transfer:HomeDirectory}</code>, and <code>${Transfer:HomeBucket}</code>.</p> <note> <p>This policy applies only when the domain of <code>ServerId</code> is Amazon S3. Amazon EFS does not use session policies.</p> <p>For session policies, Transfer Family stores the policy as a JSON blob, instead of the Amazon Resource Name (ARN) of the policy. You save the policy as a JSON blob and pass it in the <code>Policy</code> argument.</p> <p>For an example of a session policy, see <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/session-policy.html\">Example session policy</a>.</p> <p>For more information, see <a href=\"https://docs.aws.amazon.com/STS/latest/APIReference/API_AssumeRole.html\">AssumeRole</a> in the <i>Security Token Service API Reference</i>.</p> </note>"}))
    CreateAccessRequest.add_member(:posix_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: PosixProfile, location_name: 'PosixProfile'))
    CreateAccessRequest.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that controls your users' access to your Amazon S3 bucket or Amazon EFS file system. The policies attached to this role determine the level of access that you want to provide your users when transferring files into and out of your Amazon S3 bucket or Amazon EFS file system. The IAM role should also contain a trust relationship that allows the server to access your resources when servicing your users' transfer requests.</p>", "smithy.api#required" => {}}))
    CreateAccessRequest.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>A system-assigned unique identifier for a server instance. This is the specific server that you added your user to.</p>", "smithy.api#required" => {}}))
    CreateAccessRequest.add_member(:external_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ExternalId, location_name: 'ExternalId', traits: {"smithy.api#documentation" => "<p>A unique identifier that is required to identify specific groups within your directory. The users of the group that you associate have access to your Amazon S3 or Amazon EFS resources over the enabled protocols using Transfer Family. If you know the group name, you can view the SID values by running the following command using Windows PowerShell.</p> <p> <code>Get-ADGroup -Filter {samAccountName -like \"<i>YourGroupName</i>*\"} -Properties * | Select SamAccountName,ObjectSid</code> </p> <p>In that command, replace <i>YourGroupName</i> with the name of your Active Directory group.</p> <p>The regular expression used to validate this parameter is a string of characters consisting of uppercase and lowercase alphanumeric characters with no spaces. You can also include underscores or any of the following characters: =,.@:/-</p>", "smithy.api#required" => {}}))
    CreateAccessRequest.type = Types::CreateAccessRequest
    CreateAccessResponse.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>The identifier of the server that the user is attached to.</p>", "smithy.api#required" => {}}))
    CreateAccessResponse.add_member(:external_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ExternalId, location_name: 'ExternalId', traits: {"smithy.api#documentation" => "<p>The external identifier of the group whose users have access to your Amazon S3 or Amazon EFS resources over the enabled protocols using Transfer Family.</p>", "smithy.api#required" => {}}))
    CreateAccessResponse.type = Types::CreateAccessResponse
    CreateAgreementRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A name or short description to identify the agreement. </p>"}))
    CreateAgreementRequest.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>A system-assigned unique identifier for a server instance. This is the specific server that the agreement uses.</p>", "smithy.api#required" => {}}))
    CreateAgreementRequest.add_member(:local_profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'LocalProfileId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the AS2 local profile.</p>", "smithy.api#required" => {}}))
    CreateAgreementRequest.add_member(:partner_profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'PartnerProfileId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the partner profile used in the agreement.</p>", "smithy.api#required" => {}}))
    CreateAgreementRequest.add_member(:base_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'BaseDirectory', traits: {"smithy.api#documentation" => "<p>The landing directory (folder) for files transferred by using the AS2 protocol.</p> <p>A <code>BaseDirectory</code> example is <code>/<i>amzn-s3-demo-bucket</i>/home/mydirectory</code>.</p>"}))
    CreateAgreementRequest.add_member(:access_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'AccessRole', traits: {"smithy.api#documentation" => "<p>Connectors are used to send files using either the AS2 or SFTP protocol. For the access role, provide the Amazon Resource Name (ARN) of the Identity and Access Management role to use.</p> <p> <b>For AS2 connectors</b> </p> <p>With AS2, you can send files by calling <code>StartFileTransfer</code> and specifying the file paths in the request parameter, <code>SendFilePaths</code>. We use the file’s parent directory (for example, for <code>--send-file-paths /bucket/dir/file.txt</code>, parent directory is <code>/bucket/dir/</code>) to temporarily store a processed AS2 message file, store the MDN when we receive them from the partner, and write a final JSON file containing relevant metadata of the transmission. So, the <code>AccessRole</code> needs to provide read and write access to the parent directory of the file location used in the <code>StartFileTransfer</code> request. Additionally, you need to provide read and write access to the parent directory of the files that you intend to send with <code>StartFileTransfer</code>.</p> <p>If you are using Basic authentication for your AS2 connector, the access role requires the <code>secretsmanager:GetSecretValue</code> permission for the secret. If the secret is encrypted using a customer-managed key instead of the Amazon Web Services managed key in Secrets Manager, then the role also needs the <code>kms:Decrypt</code> permission for that key.</p> <p> <b>For SFTP connectors</b> </p> <p>Make sure that the access role provides read and write access to the parent directory of the file location that's used in the <code>StartFileTransfer</code> request. Additionally, make sure that the role provides <code>secretsmanager:GetSecretValue</code> permission to Secrets Manager.</p>", "smithy.api#required" => {}}))
    CreateAgreementRequest.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: AgreementStatusType, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the agreement. The agreement can be either <code>ACTIVE</code> or <code>INACTIVE</code>.</p>"}))
    CreateAgreementRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for agreements.</p>"}))
    CreateAgreementRequest.add_member(:preserve_filename, Smithy::Schema::Shapes::ShapeRef.new(shape: PreserveFilenameType, location_name: 'PreserveFilename', traits: {"smithy.api#documentation" => "<p> Determines whether or not Transfer Family appends a unique string of characters to the end of the AS2 message payload filename when saving it. </p> <ul> <li> <p> <code>ENABLED</code>: the filename provided by your trading parter is preserved when the file is saved.</p> </li> <li> <p> <code>DISABLED</code> (default value): when Transfer Family saves the file, the filename is adjusted, as described in <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/send-as2-messages.html#file-names-as2\">File names and locations</a>.</p> </li> </ul>"}))
    CreateAgreementRequest.add_member(:enforce_message_signing, Smithy::Schema::Shapes::ShapeRef.new(shape: EnforceMessageSigningType, location_name: 'EnforceMessageSigning', traits: {"smithy.api#documentation" => "<p> Determines whether or not unsigned messages from your trading partners will be accepted. </p> <ul> <li> <p> <code>ENABLED</code>: Transfer Family rejects unsigned messages from your trading partner.</p> </li> <li> <p> <code>DISABLED</code> (default value): Transfer Family accepts unsigned messages from your trading partner.</p> </li> </ul>"}))
    CreateAgreementRequest.add_member(:custom_directories, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomDirectoriesType, location_name: 'CustomDirectories', traits: {"smithy.api#documentation" => "<p>A <code>CustomDirectoriesType</code> structure. This structure specifies custom directories for storing various AS2 message files. You can specify directories for the following types of files.</p> <ul> <li> <p>Failed files</p> </li> <li> <p>MDN files</p> </li> <li> <p>Payload files</p> </li> <li> <p>Status files</p> </li> <li> <p>Temporary files</p> </li> </ul>"}))
    CreateAgreementRequest.type = Types::CreateAgreementRequest
    CreateAgreementResponse.add_member(:agreement_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AgreementId, location_name: 'AgreementId', traits: {"smithy.api#documentation" => "<p>The unique identifier for the agreement. Use this ID for deleting, or updating an agreement, as well as in any other API calls that require that you specify the agreement ID.</p>", "smithy.api#required" => {}}))
    CreateAgreementResponse.type = Types::CreateAgreementResponse
    CreateConnectorRequest.add_member(:url, Smithy::Schema::Shapes::ShapeRef.new(shape: Url, location_name: 'Url', traits: {"smithy.api#documentation" => "<p>The URL of the partner's AS2 or SFTP endpoint.</p>", "smithy.api#required" => {}}))
    CreateConnectorRequest.add_member(:as2_config, Smithy::Schema::Shapes::ShapeRef.new(shape: As2ConnectorConfig, location_name: 'As2Config', traits: {"smithy.api#documentation" => "<p>A structure that contains the parameters for an AS2 connector object.</p>"}))
    CreateConnectorRequest.add_member(:access_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'AccessRole', traits: {"smithy.api#documentation" => "<p>Connectors are used to send files using either the AS2 or SFTP protocol. For the access role, provide the Amazon Resource Name (ARN) of the Identity and Access Management role to use.</p> <p> <b>For AS2 connectors</b> </p> <p>With AS2, you can send files by calling <code>StartFileTransfer</code> and specifying the file paths in the request parameter, <code>SendFilePaths</code>. We use the file’s parent directory (for example, for <code>--send-file-paths /bucket/dir/file.txt</code>, parent directory is <code>/bucket/dir/</code>) to temporarily store a processed AS2 message file, store the MDN when we receive them from the partner, and write a final JSON file containing relevant metadata of the transmission. So, the <code>AccessRole</code> needs to provide read and write access to the parent directory of the file location used in the <code>StartFileTransfer</code> request. Additionally, you need to provide read and write access to the parent directory of the files that you intend to send with <code>StartFileTransfer</code>.</p> <p>If you are using Basic authentication for your AS2 connector, the access role requires the <code>secretsmanager:GetSecretValue</code> permission for the secret. If the secret is encrypted using a customer-managed key instead of the Amazon Web Services managed key in Secrets Manager, then the role also needs the <code>kms:Decrypt</code> permission for that key.</p> <p> <b>For SFTP connectors</b> </p> <p>Make sure that the access role provides read and write access to the parent directory of the file location that's used in the <code>StartFileTransfer</code> request. Additionally, make sure that the role provides <code>secretsmanager:GetSecretValue</code> permission to Secrets Manager.</p>", "smithy.api#required" => {}}))
    CreateConnectorRequest.add_member(:logging_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'LoggingRole', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that allows a connector to turn on CloudWatch logging for Amazon S3 events. When set, you can view connector activity in your CloudWatch logs.</p>"}))
    CreateConnectorRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for connectors. Tags are metadata attached to connectors for any purpose.</p>"}))
    CreateConnectorRequest.add_member(:sftp_config, Smithy::Schema::Shapes::ShapeRef.new(shape: SftpConnectorConfig, location_name: 'SftpConfig', traits: {"smithy.api#documentation" => "<p>A structure that contains the parameters for an SFTP connector object.</p>"}))
    CreateConnectorRequest.add_member(:security_policy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectorSecurityPolicyName, location_name: 'SecurityPolicyName', traits: {"smithy.api#documentation" => "<p>Specifies the name of the security policy for the connector.</p>"}))
    CreateConnectorRequest.type = Types::CreateConnectorRequest
    CreateConnectorResponse.add_member(:connector_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectorId, location_name: 'ConnectorId', traits: {"smithy.api#documentation" => "<p>The unique identifier for the connector, returned after the API call succeeds.</p>", "smithy.api#required" => {}}))
    CreateConnectorResponse.type = Types::CreateConnectorResponse
    CreateProfileRequest.add_member(:as2_id, Smithy::Schema::Shapes::ShapeRef.new(shape: As2Id, location_name: 'As2Id', traits: {"smithy.api#documentation" => "<p>The <code>As2Id</code> is the <i>AS2-name</i>, as defined in the <a href=\"https://datatracker.ietf.org/doc/html/rfc4130\">RFC 4130</a>. For inbound transfers, this is the <code>AS2-From</code> header for the AS2 messages sent from the partner. For outbound connectors, this is the <code>AS2-To</code> header for the AS2 messages sent to the partner using the <code>StartFileTransfer</code> API operation. This ID cannot include spaces.</p>", "smithy.api#required" => {}}))
    CreateProfileRequest.add_member(:profile_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileType, location_name: 'ProfileType', traits: {"smithy.api#documentation" => "<p>Determines the type of profile to create:</p> <ul> <li> <p>Specify <code>LOCAL</code> to create a local profile. A local profile represents the AS2-enabled Transfer Family server organization or party.</p> </li> <li> <p>Specify <code>PARTNER</code> to create a partner profile. A partner profile represents a remote organization, external to Transfer Family.</p> </li> </ul>", "smithy.api#required" => {}}))
    CreateProfileRequest.add_member(:certificate_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateIds, location_name: 'CertificateIds', traits: {"smithy.api#documentation" => "<p>An array of identifiers for the imported certificates. You use this identifier for working with profiles and partner profiles.</p>"}))
    CreateProfileRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for AS2 profiles.</p>"}))
    CreateProfileRequest.type = Types::CreateProfileRequest
    CreateProfileResponse.add_member(:profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'ProfileId', traits: {"smithy.api#documentation" => "<p>The unique identifier for the AS2 profile, returned after the API call succeeds.</p>", "smithy.api#required" => {}}))
    CreateProfileResponse.type = Types::CreateProfileResponse
    CreateServerRequest.add_member(:certificate, Smithy::Schema::Shapes::ShapeRef.new(shape: Certificate, location_name: 'Certificate', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Certificate Manager (ACM) certificate. Required when <code>Protocols</code> is set to <code>FTPS</code>.</p> <p>To request a new public certificate, see <a href=\"https://docs.aws.amazon.com/acm/latest/userguide/gs-acm-request-public.html\">Request a public certificate</a> in the <i>Certificate Manager User Guide</i>.</p> <p>To import an existing certificate into ACM, see <a href=\"https://docs.aws.amazon.com/acm/latest/userguide/import-certificate.html\">Importing certificates into ACM</a> in the <i>Certificate Manager User Guide</i>.</p> <p>To request a private certificate to use FTPS through private IP addresses, see <a href=\"https://docs.aws.amazon.com/acm/latest/userguide/gs-acm-request-private.html\">Request a private certificate</a> in the <i>Certificate Manager User Guide</i>.</p> <p>Certificates with the following cryptographic algorithms and key sizes are supported:</p> <ul> <li> <p>2048-bit RSA (RSA_2048)</p> </li> <li> <p>4096-bit RSA (RSA_4096)</p> </li> <li> <p>Elliptic Prime Curve 256 bit (EC_prime256v1)</p> </li> <li> <p>Elliptic Prime Curve 384 bit (EC_secp384r1)</p> </li> <li> <p>Elliptic Prime Curve 521 bit (EC_secp521r1)</p> </li> </ul> <note> <p>The certificate must be a valid SSL/TLS X.509 version 3 certificate with FQDN or IP address specified and information about the issuer.</p> </note>"}))
    CreateServerRequest.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: Domain, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The domain of the storage system that is used for file transfers. There are two domains available: Amazon Simple Storage Service (Amazon S3) and Amazon Elastic File System (Amazon EFS). The default value is S3.</p> <note> <p>After the server is created, the domain cannot be changed.</p> </note>"}))
    CreateServerRequest.add_member(:endpoint_details, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointDetails, location_name: 'EndpointDetails', traits: {"smithy.api#documentation" => "<p>The virtual private cloud (VPC) endpoint settings that are configured for your server. When you host your endpoint within your VPC, you can make your endpoint accessible only to resources within your VPC, or you can attach Elastic IP addresses and make your endpoint accessible to clients over the internet. Your VPC's default security groups are automatically assigned to your endpoint.</p>"}))
    CreateServerRequest.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointType, location_name: 'EndpointType', traits: {"smithy.api#documentation" => "<p>The type of endpoint that you want your server to use. You can choose to make your server's endpoint publicly accessible (PUBLIC) or host it inside your VPC. With an endpoint that is hosted in a VPC, you can restrict access to your server and resources only within your VPC or choose to make it internet facing by attaching Elastic IP addresses directly to it.</p> <note> <p> After May 19, 2021, you won't be able to create a server using <code>EndpointType=VPC_ENDPOINT</code> in your Amazon Web Services account if your account hasn't already done so before May 19, 2021. If you have already created servers with <code>EndpointType=VPC_ENDPOINT</code> in your Amazon Web Services account on or before May 19, 2021, you will not be affected. After this date, use <code>EndpointType</code>=<code>VPC</code>.</p> <p>For more information, see https://docs.aws.amazon.com/transfer/latest/userguide/create-server-in-vpc.html#deprecate-vpc-endpoint.</p> <p>It is recommended that you use <code>VPC</code> as the <code>EndpointType</code>. With this endpoint type, you have the option to directly associate up to three Elastic IPv4 addresses (BYO IP included) with your server's endpoint and use VPC security groups to restrict traffic by the client's public IP address. This is not possible with <code>EndpointType</code> set to <code>VPC_ENDPOINT</code>.</p> </note>"}))
    CreateServerRequest.add_member(:host_key, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKey, location_name: 'HostKey', traits: {"aws.cloudformation#cfnExcludeProperty" => {}, "smithy.api#documentation" => "<p>The RSA, ECDSA, or ED25519 private key to use for your SFTP-enabled server. You can add multiple host keys, in case you want to rotate keys, or have a set of active keys that use different algorithms.</p> <p>Use the following command to generate an RSA 2048 bit key with no passphrase:</p> <p> <code>ssh-keygen -t rsa -b 2048 -N \"\" -m PEM -f my-new-server-key</code>.</p> <p>Use a minimum value of 2048 for the <code>-b</code> option. You can create a stronger key by using 3072 or 4096.</p> <p>Use the following command to generate an ECDSA 256 bit key with no passphrase:</p> <p> <code>ssh-keygen -t ecdsa -b 256 -N \"\" -m PEM -f my-new-server-key</code>.</p> <p>Valid values for the <code>-b</code> option for ECDSA are 256, 384, and 521.</p> <p>Use the following command to generate an ED25519 key with no passphrase:</p> <p> <code>ssh-keygen -t ed25519 -N \"\" -f my-new-server-key</code>.</p> <p>For all of these commands, you can replace <i>my-new-server-key</i> with a string of your choice.</p> <important> <p>If you aren't planning to migrate existing users from an existing SFTP-enabled server to a new server, don't update the host key. Accidentally changing a server's host key can be disruptive.</p> </important> <p>For more information, see <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/edit-server-config.html#configuring-servers-change-host-key\">Manage host keys for your SFTP-enabled server</a> in the <i>Transfer Family User Guide</i>.</p>"}))
    CreateServerRequest.add_member(:identity_provider_details, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentityProviderDetails, location_name: 'IdentityProviderDetails', traits: {"smithy.api#documentation" => "<p>Required when <code>IdentityProviderType</code> is set to <code>AWS_DIRECTORY_SERVICE</code>, <code>Amazon Web Services_LAMBDA</code> or <code>API_GATEWAY</code>. Accepts an array containing all of the information required to use a directory in <code>AWS_DIRECTORY_SERVICE</code> or invoke a customer-supplied authentication API, including the API Gateway URL. Cannot be specified when <code>IdentityProviderType</code> is set to <code>SERVICE_MANAGED</code>.</p>"}))
    CreateServerRequest.add_member(:identity_provider_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentityProviderType, location_name: 'IdentityProviderType', traits: {"smithy.api#documentation" => "<p>The mode of authentication for a server. The default value is <code>SERVICE_MANAGED</code>, which allows you to store and access user credentials within the Transfer Family service.</p> <p>Use <code>AWS_DIRECTORY_SERVICE</code> to provide access to Active Directory groups in Directory Service for Microsoft Active Directory or Microsoft Active Directory in your on-premises environment or in Amazon Web Services using AD Connector. This option also requires you to provide a Directory ID by using the <code>IdentityProviderDetails</code> parameter.</p> <p>Use the <code>API_GATEWAY</code> value to integrate with an identity provider of your choosing. The <code>API_GATEWAY</code> setting requires you to provide an Amazon API Gateway endpoint URL to call for authentication by using the <code>IdentityProviderDetails</code> parameter.</p> <p>Use the <code>AWS_LAMBDA</code> value to directly use an Lambda function as your identity provider. If you choose this value, you must specify the ARN for the Lambda function in the <code>Function</code> parameter for the <code>IdentityProviderDetails</code> data type.</p>"}))
    CreateServerRequest.add_member(:logging_role, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableRole, location_name: 'LoggingRole', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that allows a server to turn on Amazon CloudWatch logging for Amazon S3 or Amazon EFS events. When set, you can view user activity in your CloudWatch logs.</p>"}))
    CreateServerRequest.add_member(:post_authentication_login_banner, Smithy::Schema::Shapes::ShapeRef.new(shape: PostAuthenticationLoginBanner, location_name: 'PostAuthenticationLoginBanner', traits: {"smithy.api#documentation" => "<p>Specifies a string to display when users connect to a server. This string is displayed after the user authenticates.</p> <note> <p>The SFTP protocol does not support post-authentication display banners.</p> </note>"}))
    CreateServerRequest.add_member(:pre_authentication_login_banner, Smithy::Schema::Shapes::ShapeRef.new(shape: PreAuthenticationLoginBanner, location_name: 'PreAuthenticationLoginBanner', traits: {"smithy.api#documentation" => "<p>Specifies a string to display when users connect to a server. This string is displayed before the user authenticates. For example, the following banner displays details about using the system:</p> <p> <code>This system is for the use of authorized users only. Individuals using this computer system without authority, or in excess of their authority, are subject to having all of their activities on this system monitored and recorded by system personnel.</code> </p>"}))
    CreateServerRequest.add_member(:protocols, Smithy::Schema::Shapes::ShapeRef.new(shape: Protocols, location_name: 'Protocols', traits: {"smithy.api#documentation" => "<p>Specifies the file transfer protocol or protocols over which your file transfer protocol client can connect to your server's endpoint. The available protocols are:</p> <ul> <li> <p> <code>SFTP</code> (Secure Shell (SSH) File Transfer Protocol): File transfer over SSH</p> </li> <li> <p> <code>FTPS</code> (File Transfer Protocol Secure): File transfer with TLS encryption</p> </li> <li> <p> <code>FTP</code> (File Transfer Protocol): Unencrypted file transfer</p> </li> <li> <p> <code>AS2</code> (Applicability Statement 2): used for transporting structured business-to-business data</p> </li> </ul> <note> <ul> <li> <p>If you select <code>FTPS</code>, you must choose a certificate stored in Certificate Manager (ACM) which is used to identify your server when clients connect to it over FTPS.</p> </li> <li> <p>If <code>Protocol</code> includes either <code>FTP</code> or <code>FTPS</code>, then the <code>EndpointType</code> must be <code>VPC</code> and the <code>IdentityProviderType</code> must be either <code>AWS_DIRECTORY_SERVICE</code>, <code>AWS_LAMBDA</code>, or <code>API_GATEWAY</code>.</p> </li> <li> <p>If <code>Protocol</code> includes <code>FTP</code>, then <code>AddressAllocationIds</code> cannot be associated.</p> </li> <li> <p>If <code>Protocol</code> is set only to <code>SFTP</code>, the <code>EndpointType</code> can be set to <code>PUBLIC</code> and the <code>IdentityProviderType</code> can be set any of the supported identity types: <code>SERVICE_MANAGED</code>, <code>AWS_DIRECTORY_SERVICE</code>, <code>AWS_LAMBDA</code>, or <code>API_GATEWAY</code>.</p> </li> <li> <p>If <code>Protocol</code> includes <code>AS2</code>, then the <code>EndpointType</code> must be <code>VPC</code>, and domain must be Amazon S3.</p> </li> </ul> </note>"}))
    CreateServerRequest.add_member(:protocol_details, Smithy::Schema::Shapes::ShapeRef.new(shape: ProtocolDetails, location_name: 'ProtocolDetails', traits: {"smithy.api#documentation" => "<p>The protocol settings that are configured for your server.</p> <ul> <li> <p> To indicate passive mode (for FTP and FTPS protocols), use the <code>PassiveIp</code> parameter. Enter a single dotted-quad IPv4 address, such as the external IP address of a firewall, router, or load balancer. </p> </li> <li> <p>To ignore the error that is generated when the client attempts to use the <code>SETSTAT</code> command on a file that you are uploading to an Amazon S3 bucket, use the <code>SetStatOption</code> parameter. To have the Transfer Family server ignore the <code>SETSTAT</code> command and upload files without needing to make any changes to your SFTP client, set the value to <code>ENABLE_NO_OP</code>. If you set the <code>SetStatOption</code> parameter to <code>ENABLE_NO_OP</code>, Transfer Family generates a log entry to Amazon CloudWatch Logs, so that you can determine when the client is making a <code>SETSTAT</code> call.</p> </li> <li> <p>To determine whether your Transfer Family server resumes recent, negotiated sessions through a unique session ID, use the <code>TlsSessionResumptionMode</code> parameter.</p> </li> <li> <p> <code>As2Transports</code> indicates the transport method for the AS2 messages. Currently, only HTTP is supported.</p> </li> </ul>"}))
    CreateServerRequest.add_member(:security_policy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyName, location_name: 'SecurityPolicyName', traits: {"smithy.api#documentation" => "<p>Specifies the name of the security policy for the server.</p>"}))
    CreateServerRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for servers.</p>"}))
    CreateServerRequest.add_member(:workflow_details, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkflowDetails, location_name: 'WorkflowDetails', traits: {"smithy.api#documentation" => "<p>Specifies the workflow ID for the workflow to assign and the execution role that's used for executing the workflow.</p> <p>In addition to a workflow to execute when a file is uploaded completely, <code>WorkflowDetails</code> can also contain a workflow ID (and execution role) for a workflow to execute on partial upload. A partial upload occurs when the server session disconnects while the file is still being uploaded.</p>"}))
    CreateServerRequest.add_member(:structured_log_destinations, Smithy::Schema::Shapes::ShapeRef.new(shape: StructuredLogDestinations, location_name: 'StructuredLogDestinations', traits: {"smithy.api#documentation" => "<p>Specifies the log groups to which your server logs are sent.</p> <p>To specify a log group, you must provide the ARN for an existing log group. In this case, the format of the log group is as follows:</p> <p> <code>arn:aws:logs:region-name:amazon-account-id:log-group:log-group-name:*</code> </p> <p>For example, <code>arn:aws:logs:us-east-1:111122223333:log-group:mytestgroup:*</code> </p> <p>If you have previously specified a log group for a server, you can clear it, and in effect turn off structured logging, by providing an empty value for this parameter in an <code>update-server</code> call. For example:</p> <p> <code>update-server --server-id s-1234567890abcdef0 --structured-log-destinations</code> </p>"}))
    CreateServerRequest.add_member(:s3_storage_options, Smithy::Schema::Shapes::ShapeRef.new(shape: S3StorageOptions, location_name: 'S3StorageOptions', traits: {"smithy.api#documentation" => "<p>Specifies whether or not performance for your Amazon S3 directories is optimized. This is disabled by default.</p> <p>By default, home directory mappings have a <code>TYPE</code> of <code>DIRECTORY</code>. If you enable this option, you would then need to explicitly set the <code>HomeDirectoryMapEntry</code> <code>Type</code> to <code>FILE</code> if you want a mapping to have a file target.</p>"}))
    CreateServerRequest.add_member(:ip_address_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddressType, location_name: 'IpAddressType', traits: {"smithy.api#documentation" => "<p>Specifies whether to use IPv4 only, or to use dual-stack (IPv4 and IPv6) for your Transfer Family endpoint. The default value is <code>IPV4</code>.</p> <important> <p>The <code>IpAddressType</code> parameter has the following limitations:</p> <ul> <li> <p>It cannot be changed while the server is online. You must stop the server before modifying this parameter.</p> </li> <li> <p>It cannot be updated to <code>DUALSTACK</code> if the server has <code>AddressAllocationIds</code> specified.</p> </li> </ul> </important> <note> <p>When using <code>DUALSTACK</code> as the <code>IpAddressType</code>, you cannot set the <code>AddressAllocationIds</code> parameter for the <a href=\"https://docs.aws.amazon.com/transfer/latest/APIReference/API_EndpointDetails.html\">EndpointDetails</a> for the server.</p> </note>"}))
    CreateServerRequest.type = Types::CreateServerRequest
    CreateServerResponse.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>The service-assigned identifier of the server that is created.</p>", "smithy.api#required" => {}}))
    CreateServerResponse.type = Types::CreateServerResponse
    CreateUserRequest.add_member(:home_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'HomeDirectory', traits: {"smithy.api#documentation" => "<p>The landing directory (folder) for a user when they log in to the server using the client.</p> <p>A <code>HomeDirectory</code> example is <code>/bucket_name/home/mydirectory</code>.</p> <note> <p>You can use the <code>HomeDirectory</code> parameter for <code>HomeDirectoryType</code> when it is set to either <code>PATH</code> or <code>LOGICAL</code>.</p> </note>"}))
    CreateUserRequest.add_member(:home_directory_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryType, location_name: 'HomeDirectoryType', traits: {"smithy.api#documentation" => "<p>The type of landing directory (folder) that you want your users' home directory to be when they log in to the server. If you set it to <code>PATH</code>, the user will see the absolute Amazon S3 bucket or Amazon EFS path as is in their file transfer protocol clients. If you set it to <code>LOGICAL</code>, you need to provide mappings in the <code>HomeDirectoryMappings</code> for how you want to make Amazon S3 or Amazon EFS paths visible to your users.</p> <note> <p>If <code>HomeDirectoryType</code> is <code>LOGICAL</code>, you must provide mappings, using the <code>HomeDirectoryMappings</code> parameter. If, on the other hand, <code>HomeDirectoryType</code> is <code>PATH</code>, you provide an absolute path using the <code>HomeDirectory</code> parameter. You cannot have both <code>HomeDirectory</code> and <code>HomeDirectoryMappings</code> in your template.</p> </note>"}))
    CreateUserRequest.add_member(:home_directory_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryMappings, location_name: 'HomeDirectoryMappings', traits: {"smithy.api#documentation" => "<p>Logical directory mappings that specify what Amazon S3 or Amazon EFS paths and keys should be visible to your user and how you want to make them visible. You must specify the <code>Entry</code> and <code>Target</code> pair, where <code>Entry</code> shows how the path is made visible and <code>Target</code> is the actual Amazon S3 or Amazon EFS path. If you only specify a target, it is displayed as is. You also must ensure that your Identity and Access Management (IAM) role provides access to paths in <code>Target</code>. This value can be set only when <code>HomeDirectoryType</code> is set to <i>LOGICAL</i>.</p> <p>The following is an <code>Entry</code> and <code>Target</code> pair example.</p> <p> <code>[ { \"Entry\": \"/directory1\", \"Target\": \"/bucket_name/home/mydirectory\" } ]</code> </p> <p>In most cases, you can use this value instead of the session policy to lock your user down to the designated home directory (\"<code>chroot</code>\"). To do this, you can set <code>Entry</code> to <code>/</code> and set <code>Target</code> to the value the user should see for their home directory when they log in.</p> <p>The following is an <code>Entry</code> and <code>Target</code> pair example for <code>chroot</code>.</p> <p> <code>[ { \"Entry\": \"/\", \"Target\": \"/bucket_name/home/mydirectory\" } ]</code> </p>"}))
    CreateUserRequest.add_member(:policy, Smithy::Schema::Shapes::ShapeRef.new(shape: Policy, location_name: 'Policy', traits: {"smithy.api#documentation" => "<p>A session policy for your user so that you can use the same Identity and Access Management (IAM) role across multiple users. This policy scopes down a user's access to portions of their Amazon S3 bucket. Variables that you can use inside this policy include <code>${Transfer:UserName}</code>, <code>${Transfer:HomeDirectory}</code>, and <code>${Transfer:HomeBucket}</code>.</p> <note> <p>This policy applies only when the domain of <code>ServerId</code> is Amazon S3. Amazon EFS does not use session policies.</p> <p>For session policies, Transfer Family stores the policy as a JSON blob, instead of the Amazon Resource Name (ARN) of the policy. You save the policy as a JSON blob and pass it in the <code>Policy</code> argument.</p> <p>For an example of a session policy, see <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/session-policy.html\">Example session policy</a>.</p> <p>For more information, see <a href=\"https://docs.aws.amazon.com/STS/latest/APIReference/API_AssumeRole.html\">AssumeRole</a> in the <i>Amazon Web Services Security Token Service API Reference</i>.</p> </note>"}))
    CreateUserRequest.add_member(:posix_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: PosixProfile, location_name: 'PosixProfile', traits: {"smithy.api#documentation" => "<p>Specifies the full POSIX identity, including user ID (<code>Uid</code>), group ID (<code>Gid</code>), and any secondary groups IDs (<code>SecondaryGids</code>), that controls your users' access to your Amazon EFS file systems. The POSIX permissions that are set on files and directories in Amazon EFS determine the level of access your users get when transferring files into and out of your Amazon EFS file systems.</p>"}))
    CreateUserRequest.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that controls your users' access to your Amazon S3 bucket or Amazon EFS file system. The policies attached to this role determine the level of access that you want to provide your users when transferring files into and out of your Amazon S3 bucket or Amazon EFS file system. The IAM role should also contain a trust relationship that allows the server to access your resources when servicing your users' transfer requests.</p>", "smithy.api#required" => {}}))
    CreateUserRequest.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>A system-assigned unique identifier for a server instance. This is the specific server that you added your user to.</p>", "smithy.api#required" => {}}))
    CreateUserRequest.add_member(:ssh_public_key_body, Smithy::Schema::Shapes::ShapeRef.new(shape: SshPublicKeyBody, location_name: 'SshPublicKeyBody', traits: {"aws.cloudformation#cfnExcludeProperty" => {}, "smithy.api#documentation" => "<p>The public portion of the Secure Shell (SSH) key used to authenticate the user to the server.</p> <p>The three standard SSH public key format elements are <code>&lt;key type&gt;</code>, <code>&lt;body base64&gt;</code>, and an optional <code>&lt;comment&gt;</code>, with spaces between each element.</p> <p>Transfer Family accepts RSA, ECDSA, and ED25519 keys.</p> <ul> <li> <p>For RSA keys, the key type is <code>ssh-rsa</code>.</p> </li> <li> <p>For ED25519 keys, the key type is <code>ssh-ed25519</code>.</p> </li> <li> <p>For ECDSA keys, the key type is either <code>ecdsa-sha2-nistp256</code>, <code>ecdsa-sha2-nistp384</code>, or <code>ecdsa-sha2-nistp521</code>, depending on the size of the key you generated.</p> </li> </ul>"}))
    CreateUserRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for users. Tags are metadata attached to users for any purpose.</p>"}))
    CreateUserRequest.add_member(:user_name, Smithy::Schema::Shapes::ShapeRef.new(shape: UserName, location_name: 'UserName', traits: {"smithy.api#documentation" => "<p>A unique string that identifies a user and is associated with a <code>ServerId</code>. This user name must be a minimum of 3 and a maximum of 100 characters long. The following are valid characters: a-z, A-Z, 0-9, underscore '_', hyphen '-', period '.', and at sign '@'. The user name can't start with a hyphen, period, or at sign.</p>", "smithy.api#required" => {}}))
    CreateUserRequest.type = Types::CreateUserRequest
    CreateUserResponse.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>The identifier of the server that the user is attached to.</p>", "smithy.api#required" => {}}))
    CreateUserResponse.add_member(:user_name, Smithy::Schema::Shapes::ShapeRef.new(shape: UserName, location_name: 'UserName', traits: {"smithy.api#documentation" => "<p>A unique string that identifies a Transfer Family user.</p>", "smithy.api#required" => {}}))
    CreateUserResponse.type = Types::CreateUserResponse
    CreateWebAppRequest.add_member(:identity_provider_details, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppIdentityProviderDetails, location_name: 'IdentityProviderDetails', traits: {"smithy.api#documentation" => "<p>You can provide a structure that contains the details for the identity provider to use with your web app.</p> <p>For more details about this parameter, see <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/webapp-identity-center.html\">Configure your identity provider for Transfer Family web apps</a>.</p>", "smithy.api#required" => {}}))
    CreateWebAppRequest.add_member(:access_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppAccessEndpoint, location_name: 'AccessEndpoint', traits: {"smithy.api#documentation" => "<p>The <code>AccessEndpoint</code> is the URL that you provide to your users for them to interact with the Transfer Family web app. You can specify a custom URL or use the default value.</p> <p>Before you enter a custom URL for this parameter, follow the steps described in <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/webapp-customize.html\">Update your access endpoint with a custom URL</a>.</p>"}))
    CreateWebAppRequest.add_member(:web_app_units, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppUnits, location_name: 'WebAppUnits', traits: {"smithy.api#documentation" => "<p>A union that contains the value for number of concurrent connections or the user sessions on your web app.</p>"}))
    CreateWebAppRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for web apps.</p>"}))
    CreateWebAppRequest.add_member(:web_app_endpoint_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppEndpointPolicy, location_name: 'WebAppEndpointPolicy', traits: {"smithy.api#documentation" => "<p> Setting for the type of endpoint policy for the web app. The default value is <code>STANDARD</code>. </p> <p>If you are creating the web app in an Amazon Web Services GovCloud (US) Region, you can set this parameter to <code>FIPS</code>.</p>"}))
    CreateWebAppRequest.type = Types::CreateWebAppRequest
    CreateWebAppResponse.add_member(:web_app_id, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppId, location_name: 'WebAppId', traits: {"smithy.api#documentation" => "<p>Returns a unique identifier for the web app.</p>", "smithy.api#required" => {}}))
    CreateWebAppResponse.type = Types::CreateWebAppResponse
    CreateWorkflowRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkflowDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A textual description for the workflow.</p>"}))
    CreateWorkflowRequest.add_member(:steps, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkflowSteps, location_name: 'Steps', traits: {"smithy.api#documentation" => "<p>Specifies the details for the steps that are in the specified workflow.</p> <p> The <code>TYPE</code> specifies which of the following actions is being taken for this step. </p> <ul> <li> <p> <b> <code>COPY</code> </b> - Copy the file to another location.</p> </li> <li> <p> <b> <code>CUSTOM</code> </b> - Perform a custom step with an Lambda function target.</p> </li> <li> <p> <b> <code>DECRYPT</code> </b> - Decrypt a file that was encrypted before it was uploaded.</p> </li> <li> <p> <b> <code>DELETE</code> </b> - Delete the file.</p> </li> <li> <p> <b> <code>TAG</code> </b> - Add a tag to the file.</p> </li> </ul> <note> <p> Currently, copying and tagging are supported only on S3. </p> </note> <p> For file location, you specify either the Amazon S3 bucket and key, or the Amazon EFS file system ID and path. </p>", "smithy.api#required" => {}}))
    CreateWorkflowRequest.add_member(:on_exception_steps, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkflowSteps, location_name: 'OnExceptionSteps', traits: {"smithy.api#documentation" => "<p>Specifies the steps (actions) to take if errors are encountered during execution of the workflow.</p> <note> <p>For custom steps, the Lambda function needs to send <code>FAILURE</code> to the call back API to kick off the exception steps. Additionally, if the Lambda does not send <code>SUCCESS</code> before it times out, the exception steps are executed.</p> </note>"}))
    CreateWorkflowRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for workflows. Tags are metadata attached to workflows for any purpose.</p>"}))
    CreateWorkflowRequest.type = Types::CreateWorkflowRequest
    CreateWorkflowResponse.add_member(:workflow_id, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkflowId, location_name: 'WorkflowId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the workflow.</p>", "smithy.api#required" => {}}))
    CreateWorkflowResponse.type = Types::CreateWorkflowResponse
    CustomDirectoriesType.add_member(:failed_files_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'FailedFilesDirectory', traits: {"smithy.api#documentation" => "<p>Specifies a location to store failed AS2 message files.</p>", "smithy.api#required" => {}}))
    CustomDirectoriesType.add_member(:mdn_files_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'MdnFilesDirectory', traits: {"smithy.api#documentation" => "<p>Specifies a location to store MDN files.</p>", "smithy.api#required" => {}}))
    CustomDirectoriesType.add_member(:payload_files_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'PayloadFilesDirectory', traits: {"smithy.api#documentation" => "<p>Specifies a location to store the payload for AS2 message files.</p>", "smithy.api#required" => {}}))
    CustomDirectoriesType.add_member(:status_files_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'StatusFilesDirectory', traits: {"smithy.api#documentation" => "<p>Specifies a location to store AS2 status messages.</p>", "smithy.api#required" => {}}))
    CustomDirectoriesType.add_member(:temporary_files_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'TemporaryFilesDirectory', traits: {"smithy.api#documentation" => "<p>Specifies a location to store temporary AS2 message files.</p>", "smithy.api#required" => {}}))
    CustomDirectoriesType.type = Types::CustomDirectoriesType
    CustomStepDetails.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkflowStepName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the step, used as an identifier.</p>"}))
    CustomStepDetails.add_member(:target, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomStepTarget, location_name: 'Target', traits: {"smithy.api#documentation" => "<p>The ARN for the Lambda function that is being called.</p>"}))
