    DescribedAccess.add_member(:home_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'HomeDirectory', traits: {"smithy.api#documentation" => "<p>The landing directory (folder) for a user when they log in to the server using the client.</p> <p>A <code>HomeDirectory</code> example is <code>/bucket_name/home/mydirectory</code>.</p> <note> <p>You can use the <code>HomeDirectory</code> parameter for <code>HomeDirectoryType</code> when it is set to either <code>PATH</code> or <code>LOGICAL</code>.</p> </note>"}))
    DescribedAccess.add_member(:home_directory_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryMappings, location_name: 'HomeDirectoryMappings', traits: {"smithy.api#documentation" => "<p>Logical directory mappings that specify what Amazon S3 or Amazon EFS paths and keys should be visible to your user and how you want to make them visible. You must specify the <code>Entry</code> and <code>Target</code> pair, where <code>Entry</code> shows how the path is made visible and <code>Target</code> is the actual Amazon S3 or Amazon EFS path. If you only specify a target, it is displayed as is. You also must ensure that your Identity and Access Management (IAM) role provides access to paths in <code>Target</code>. This value can be set only when <code>HomeDirectoryType</code> is set to <i>LOGICAL</i>.</p> <p>In most cases, you can use this value instead of the session policy to lock down the associated access to the designated home directory (\"<code>chroot</code>\"). To do this, you can set <code>Entry</code> to '/' and set <code>Target</code> to the <code>HomeDirectory</code> parameter value.</p>"}))
    DescribedAccess.add_member(:home_directory_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryType, location_name: 'HomeDirectoryType', traits: {"smithy.api#documentation" => "<p>The type of landing directory (folder) that you want your users' home directory to be when they log in to the server. If you set it to <code>PATH</code>, the user will see the absolute Amazon S3 bucket or Amazon EFS path as is in their file transfer protocol clients. If you set it to <code>LOGICAL</code>, you need to provide mappings in the <code>HomeDirectoryMappings</code> for how you want to make Amazon S3 or Amazon EFS paths visible to your users.</p> <note> <p>If <code>HomeDirectoryType</code> is <code>LOGICAL</code>, you must provide mappings, using the <code>HomeDirectoryMappings</code> parameter. If, on the other hand, <code>HomeDirectoryType</code> is <code>PATH</code>, you provide an absolute path using the <code>HomeDirectory</code> parameter. You cannot have both <code>HomeDirectory</code> and <code>HomeDirectoryMappings</code> in your template.</p> </note>"}))
    DescribedAccess.add_member(:policy, Smithy::Schema::Shapes::ShapeRef.new(shape: Policy, location_name: 'Policy', traits: {"smithy.api#documentation" => "<p>A session policy for your user so that you can use the same Identity and Access Management (IAM) role across multiple users. This policy scopes down a user's access to portions of their Amazon S3 bucket. Variables that you can use inside this policy include <code>${Transfer:UserName}</code>, <code>${Transfer:HomeDirectory}</code>, and <code>${Transfer:HomeBucket}</code>.</p>"}))
    DescribedAccess.add_member(:posix_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: PosixProfile, location_name: 'PosixProfile'))
    DescribedAccess.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that controls your users' access to your Amazon S3 bucket or Amazon EFS file system. The policies attached to this role determine the level of access that you want to provide your users when transferring files into and out of your Amazon S3 bucket or Amazon EFS file system. The IAM role should also contain a trust relationship that allows the server to access your resources when servicing your users' transfer requests.</p>"}))
    DescribedAccess.add_member(:external_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ExternalId, location_name: 'ExternalId', traits: {"smithy.api#documentation" => "<p>A unique identifier that is required to identify specific groups within your directory. The users of the group that you associate have access to your Amazon S3 or Amazon EFS resources over the enabled protocols using Transfer Family. If you know the group name, you can view the SID values by running the following command using Windows PowerShell.</p> <p> <code>Get-ADGroup -Filter {samAccountName -like \"<i>YourGroupName</i>*\"} -Properties * | Select SamAccountName,ObjectSid</code> </p> <p>In that command, replace <i>YourGroupName</i> with the name of your Active Directory group.</p> <p>The regular expression used to validate this parameter is a string of characters consisting of uppercase and lowercase alphanumeric characters with no spaces. You can also include underscores or any of the following characters: =,.@:/-</p>"}))
    DescribedAccess.type = Types::DescribedAccess
    DescribedAgreement.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'Arn', traits: {"aws.cloudformation#cfnMutability" => "read", "smithy.api#documentation" => "<p>The unique Amazon Resource Name (ARN) for the agreement.</p>", "smithy.api#required" => {}}))
    DescribedAgreement.add_member(:agreement_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AgreementId, location_name: 'AgreementId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the agreement. This identifier is returned when you create an agreement.</p>"}))
    DescribedAgreement.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>The name or short description that's used to identify the agreement.</p>"}))
    DescribedAgreement.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: AgreementStatusType, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The current status of the agreement, either <code>ACTIVE</code> or <code>INACTIVE</code>.</p>"}))
    DescribedAgreement.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>A system-assigned unique identifier for a server instance. This identifier indicates the specific server that the agreement uses.</p>"}))
    DescribedAgreement.add_member(:local_profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'LocalProfileId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the AS2 local profile.</p>"}))
    DescribedAgreement.add_member(:partner_profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'PartnerProfileId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the partner profile used in the agreement.</p>"}))
    DescribedAgreement.add_member(:base_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'BaseDirectory', traits: {"smithy.api#documentation" => "<p>The landing directory (folder) for files that are transferred by using the AS2 protocol.</p>"}))
    DescribedAgreement.add_member(:access_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'AccessRole', traits: {"smithy.api#documentation" => "<p>Connectors are used to send files using either the AS2 or SFTP protocol. For the access role, provide the Amazon Resource Name (ARN) of the Identity and Access Management role to use.</p> <p> <b>For AS2 connectors</b> </p> <p>With AS2, you can send files by calling <code>StartFileTransfer</code> and specifying the file paths in the request parameter, <code>SendFilePaths</code>. We use the file’s parent directory (for example, for <code>--send-file-paths /bucket/dir/file.txt</code>, parent directory is <code>/bucket/dir/</code>) to temporarily store a processed AS2 message file, store the MDN when we receive them from the partner, and write a final JSON file containing relevant metadata of the transmission. So, the <code>AccessRole</code> needs to provide read and write access to the parent directory of the file location used in the <code>StartFileTransfer</code> request. Additionally, you need to provide read and write access to the parent directory of the files that you intend to send with <code>StartFileTransfer</code>.</p> <p>If you are using Basic authentication for your AS2 connector, the access role requires the <code>secretsmanager:GetSecretValue</code> permission for the secret. If the secret is encrypted using a customer-managed key instead of the Amazon Web Services managed key in Secrets Manager, then the role also needs the <code>kms:Decrypt</code> permission for that key.</p> <p> <b>For SFTP connectors</b> </p> <p>Make sure that the access role provides read and write access to the parent directory of the file location that's used in the <code>StartFileTransfer</code> request. Additionally, make sure that the role provides <code>secretsmanager:GetSecretValue</code> permission to Secrets Manager.</p>"}))
    DescribedAgreement.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for agreements.</p>"}))
    DescribedAgreement.add_member(:preserve_filename, Smithy::Schema::Shapes::ShapeRef.new(shape: PreserveFilenameType, location_name: 'PreserveFilename', traits: {"smithy.api#documentation" => "<p> Determines whether or not Transfer Family appends a unique string of characters to the end of the AS2 message payload filename when saving it. </p> <ul> <li> <p> <code>ENABLED</code>: the filename provided by your trading parter is preserved when the file is saved.</p> </li> <li> <p> <code>DISABLED</code> (default value): when Transfer Family saves the file, the filename is adjusted, as described in <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/send-as2-messages.html#file-names-as2\">File names and locations</a>.</p> </li> </ul>"}))
    DescribedAgreement.add_member(:enforce_message_signing, Smithy::Schema::Shapes::ShapeRef.new(shape: EnforceMessageSigningType, location_name: 'EnforceMessageSigning', traits: {"smithy.api#documentation" => "<p> Determines whether or not unsigned messages from your trading partners will be accepted. </p> <ul> <li> <p> <code>ENABLED</code>: Transfer Family rejects unsigned messages from your trading partner.</p> </li> <li> <p> <code>DISABLED</code> (default value): Transfer Family accepts unsigned messages from your trading partner.</p> </li> </ul>"}))
    DescribedAgreement.add_member(:custom_directories, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomDirectoriesType, location_name: 'CustomDirectories', traits: {"smithy.api#documentation" => "<p>A <code>CustomDirectoriesType</code> structure. This structure specifies custom directories for storing various AS2 message files. You can specify directories for the following types of files.</p> <ul> <li> <p>Failed files</p> </li> <li> <p>MDN files</p> </li> <li> <p>Payload files</p> </li> <li> <p>Status files</p> </li> <li> <p>Temporary files</p> </li> </ul>"}))
    DescribedAgreement.type = Types::DescribedAgreement
    DescribedCertificate.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'Arn', traits: {"aws.cloudformation#cfnMutability" => "read", "smithy.api#documentation" => "<p>The unique Amazon Resource Name (ARN) for the certificate.</p>", "smithy.api#required" => {}}))
    DescribedCertificate.add_member(:certificate_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateId, location_name: 'CertificateId', traits: {"smithy.api#documentation" => "<p>An array of identifiers for the imported certificates. You use this identifier for working with profiles and partner profiles.</p>"}))
    DescribedCertificate.add_member(:usage, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateUsageType, location_name: 'Usage', traits: {"smithy.api#documentation" => "<p>Specifies how this certificate is used. It can be used in the following ways:</p> <ul> <li> <p> <code>SIGNING</code>: For signing AS2 messages</p> </li> <li> <p> <code>ENCRYPTION</code>: For encrypting AS2 messages</p> </li> <li> <p> <code>TLS</code>: For securing AS2 communications sent over HTTPS</p> </li> </ul>"}))
    DescribedCertificate.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateStatusType, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>A certificate's status can be either <code>ACTIVE</code> or <code>INACTIVE</code>.</p> <p>You can set <code>ActiveDate</code> and <code>InactiveDate</code> in the <code>UpdateCertificate</code> call. If you set values for these parameters, those values are used to determine whether the certificate has a status of <code>ACTIVE</code> or <code>INACTIVE</code>.</p> <p>If you don't set values for <code>ActiveDate</code> and <code>InactiveDate</code>, we use the <code>NotBefore</code> and <code>NotAfter</code> date as specified on the X509 certificate to determine when a certificate is active and when it is inactive.</p>"}))
    DescribedCertificate.add_member(:certificate, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateBodyType, location_name: 'Certificate', traits: {"smithy.api#documentation" => "<p>The file name for the certificate.</p>"}))
    DescribedCertificate.add_member(:certificate_chain, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateChainType, location_name: 'CertificateChain', traits: {"smithy.api#documentation" => "<p>The list of certificates that make up the chain for the certificate.</p>"}))
    DescribedCertificate.add_member(:active_date, Smithy::Schema::Shapes::ShapeRef.new(shape: CertDate, location_name: 'ActiveDate', traits: {"smithy.api#documentation" => "<p>An optional date that specifies when the certificate becomes active. If you do not specify a value, <code>ActiveDate</code> takes the same value as <code>NotBeforeDate</code>, which is specified by the CA. </p>"}))
    DescribedCertificate.add_member(:inactive_date, Smithy::Schema::Shapes::ShapeRef.new(shape: CertDate, location_name: 'InactiveDate', traits: {"smithy.api#documentation" => "<p>An optional date that specifies when the certificate becomes inactive. If you do not specify a value, <code>InactiveDate</code> takes the same value as <code>NotAfterDate</code>, which is specified by the CA.</p>"}))
    DescribedCertificate.add_member(:serial, Smithy::Schema::Shapes::ShapeRef.new(shape: CertSerial, location_name: 'Serial', traits: {"smithy.api#documentation" => "<p>The serial number for the certificate.</p>"}))
    DescribedCertificate.add_member(:not_before_date, Smithy::Schema::Shapes::ShapeRef.new(shape: CertDate, location_name: 'NotBeforeDate', traits: {"smithy.api#documentation" => "<p>The earliest date that the certificate is valid.</p>"}))
    DescribedCertificate.add_member(:not_after_date, Smithy::Schema::Shapes::ShapeRef.new(shape: CertDate, location_name: 'NotAfterDate', traits: {"smithy.api#documentation" => "<p>The final date that the certificate is valid.</p>"}))
    DescribedCertificate.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateType, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>If a private key has been specified for the certificate, its type is <code>CERTIFICATE_WITH_PRIVATE_KEY</code>. If there is no private key, the type is <code>CERTIFICATE</code>.</p>"}))
    DescribedCertificate.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>The name or description that's used to identity the certificate. </p>"}))
    DescribedCertificate.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for certificates.</p>"}))
    DescribedCertificate.type = Types::DescribedCertificate
    DescribedConnector.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>The unique Amazon Resource Name (ARN) for the connector.</p>", "smithy.api#required" => {}}))
