    DescribedConnector.add_member(:url, Smithy::Schema::Shapes::ShapeRef.new(shape: Url, location_name: 'Url', traits: {"smithy.api#documentation" => "<p>The URL of the partner's AS2 or SFTP endpoint.</p>"}))
    DescribedConnector.add_member(:as2_config, Smithy::Schema::Shapes::ShapeRef.new(shape: As2ConnectorConfig, location_name: 'As2Config', traits: {"smithy.api#documentation" => "<p>A structure that contains the parameters for an AS2 connector object.</p>"}))
    DescribedConnector.add_member(:access_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'AccessRole', traits: {"smithy.api#documentation" => "<p>Connectors are used to send files using either the AS2 or SFTP protocol. For the access role, provide the Amazon Resource Name (ARN) of the Identity and Access Management role to use.</p> <p> <b>For AS2 connectors</b> </p> <p>With AS2, you can send files by calling <code>StartFileTransfer</code> and specifying the file paths in the request parameter, <code>SendFilePaths</code>. We use the file’s parent directory (for example, for <code>--send-file-paths /bucket/dir/file.txt</code>, parent directory is <code>/bucket/dir/</code>) to temporarily store a processed AS2 message file, store the MDN when we receive them from the partner, and write a final JSON file containing relevant metadata of the transmission. So, the <code>AccessRole</code> needs to provide read and write access to the parent directory of the file location used in the <code>StartFileTransfer</code> request. Additionally, you need to provide read and write access to the parent directory of the files that you intend to send with <code>StartFileTransfer</code>.</p> <p>If you are using Basic authentication for your AS2 connector, the access role requires the <code>secretsmanager:GetSecretValue</code> permission for the secret. If the secret is encrypted using a customer-managed key instead of the Amazon Web Services managed key in Secrets Manager, then the role also needs the <code>kms:Decrypt</code> permission for that key.</p> <p> <b>For SFTP connectors</b> </p> <p>Make sure that the access role provides read and write access to the parent directory of the file location that's used in the <code>StartFileTransfer</code> request. Additionally, make sure that the role provides <code>secretsmanager:GetSecretValue</code> permission to Secrets Manager.</p>"}))
    DescribedConnector.add_member(:logging_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'LoggingRole', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that allows a connector to turn on CloudWatch logging for Amazon S3 events. When set, you can view connector activity in your CloudWatch logs.</p>"}))
    DescribedConnector.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for connectors.</p>"}))
    DescribedConnector.add_member(:sftp_config, Smithy::Schema::Shapes::ShapeRef.new(shape: SftpConnectorConfig, location_name: 'SftpConfig', traits: {"smithy.api#documentation" => "<p>A structure that contains the parameters for an SFTP connector object.</p>"}))
    DescribedConnector.add_member(:service_managed_egress_ip_addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceManagedEgressIpAddresses, location_name: 'ServiceManagedEgressIpAddresses', traits: {"smithy.api#documentation" => "<p>The list of egress IP addresses of this connector. These IP addresses are assigned automatically when you create the connector.</p>"}))
    DescribedConnector.add_member(:security_policy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectorSecurityPolicyName, location_name: 'SecurityPolicyName', traits: {"smithy.api#documentation" => "<p>The text name of the security policy for the specified connector.</p>"}))
    DescribedConnector.type = Types::DescribedConnector
    DescribedExecution.add_member(:execution_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionId, location_name: 'ExecutionId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the execution of a workflow.</p>"}))
    DescribedExecution.add_member(:initial_file_location, Smithy::Schema::Shapes::ShapeRef.new(shape: FileLocation, location_name: 'InitialFileLocation', traits: {"smithy.api#documentation" => "<p>A structure that describes the Amazon S3 or EFS file location. This is the file location when the execution begins: if the file is being copied, this is the initial (as opposed to destination) file location.</p>"}))
    DescribedExecution.add_member(:service_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceMetadata, location_name: 'ServiceMetadata', traits: {"smithy.api#documentation" => "<p>A container object for the session details that are associated with a workflow.</p>"}))
    DescribedExecution.add_member(:execution_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'ExecutionRole', traits: {"smithy.api#documentation" => "<p>The IAM role associated with the execution.</p>"}))
    DescribedExecution.add_member(:logging_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LoggingConfiguration, location_name: 'LoggingConfiguration', traits: {"smithy.api#documentation" => "<p>The IAM logging role associated with the execution.</p>"}))
    DescribedExecution.add_member(:posix_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: PosixProfile, location_name: 'PosixProfile'))
    DescribedExecution.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status is one of the execution. Can be in progress, completed, exception encountered, or handling the exception. </p>"}))
    DescribedExecution.add_member(:results, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionResults, location_name: 'Results', traits: {"smithy.api#documentation" => "<p>A structure that describes the execution results. This includes a list of the steps along with the details of each step, error type and message (if any), and the <code>OnExceptionSteps</code> structure.</p>"}))
    DescribedExecution.type = Types::DescribedExecution
    DescribedHostKey.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>The unique Amazon Resource Name (ARN) for the host key.</p>", "smithy.api#required" => {}}))
    DescribedHostKey.add_member(:host_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKeyId, location_name: 'HostKeyId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the host key.</p>"}))
    DescribedHostKey.add_member(:host_key_fingerprint, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKeyFingerprint, location_name: 'HostKeyFingerprint', traits: {"smithy.api#documentation" => "<p>The public key fingerprint, which is a short sequence of bytes used to identify the longer public key.</p>"}))
    DescribedHostKey.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKeyDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>The text description for this host key.</p>"}))
    DescribedHostKey.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKeyType, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>The encryption algorithm that is used for the host key. The <code>Type</code> parameter is specified by using one of the following values:</p> <ul> <li> <p> <code>ssh-rsa</code> </p> </li> <li> <p> <code>ssh-ed25519</code> </p> </li> <li> <p> <code>ecdsa-sha2-nistp256</code> </p> </li> <li> <p> <code>ecdsa-sha2-nistp384</code> </p> </li> <li> <p> <code>ecdsa-sha2-nistp521</code> </p> </li> </ul>"}))
    DescribedHostKey.add_member(:date_imported, Smithy::Schema::Shapes::ShapeRef.new(shape: DateImported, location_name: 'DateImported', traits: {"smithy.api#documentation" => "<p>The date on which the host key was added to the server.</p>"}))
    DescribedHostKey.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for host keys.</p>"}))
    DescribedHostKey.type = Types::DescribedHostKey
    DescribedIdentityCenterConfig.add_member(:application_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentityCenterApplicationArn, location_name: 'ApplicationArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the IAM Identity Center application: this value is set automatically when you create your web app.</p>"}))
    DescribedIdentityCenterConfig.add_member(:instance_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentityCenterInstanceArn, location_name: 'InstanceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the IAM Identity Center used for the web app.</p>"}))
    DescribedIdentityCenterConfig.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The IAM role in IAM Identity Center used for the web app.</p>"}))
    DescribedIdentityCenterConfig.type = Types::DescribedIdentityCenterConfig
    DescribedProfile.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>The unique Amazon Resource Name (ARN) for the profile.</p>", "smithy.api#required" => {}}))
    DescribedProfile.add_member(:profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'ProfileId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the local or partner AS2 profile.</p>"}))
    DescribedProfile.add_member(:profile_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileType, location_name: 'ProfileType', traits: {"smithy.api#documentation" => "<p>Indicates whether to list only <code>LOCAL</code> type profiles or only <code>PARTNER</code> type profiles. If not supplied in the request, the command lists all types of profiles.</p>"}))
    DescribedProfile.add_member(:as2_id, Smithy::Schema::Shapes::ShapeRef.new(shape: As2Id, location_name: 'As2Id', traits: {"smithy.api#documentation" => "<p>The <code>As2Id</code> is the <i>AS2-name</i>, as defined in the <a href=\"https://datatracker.ietf.org/doc/html/rfc4130\">RFC 4130</a>. For inbound transfers, this is the <code>AS2-From</code> header for the AS2 messages sent from the partner. For outbound connectors, this is the <code>AS2-To</code> header for the AS2 messages sent to the partner using the <code>StartFileTransfer</code> API operation. This ID cannot include spaces.</p>"}))
    DescribedProfile.add_member(:certificate_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateIds, location_name: 'CertificateIds', traits: {"smithy.api#documentation" => "<p>An array of identifiers for the imported certificates. You use this identifier for working with profiles and partner profiles.</p>"}))
    DescribedProfile.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for profiles.</p>"}))
    DescribedProfile.type = Types::DescribedProfile
    DescribedSecurityPolicy.add_member(:fips, Smithy::Schema::Shapes::ShapeRef.new(shape: Fips, location_name: 'Fips', traits: {"smithy.api#documentation" => "<p>Specifies whether this policy enables Federal Information Processing Standards (FIPS). This parameter applies to both server and connector security policies.</p>"}))
    DescribedSecurityPolicy.add_member(:security_policy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyName, location_name: 'SecurityPolicyName', traits: {"smithy.api#documentation" => "<p>The text name of the specified security policy.</p>", "smithy.api#required" => {}}))
    DescribedSecurityPolicy.add_member(:ssh_ciphers, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyOptions, location_name: 'SshCiphers', traits: {"smithy.api#documentation" => "<p>Lists the enabled Secure Shell (SSH) cipher encryption algorithms in the security policy that is attached to the server or connector. This parameter applies to both server and connector security policies.</p>"}))
    DescribedSecurityPolicy.add_member(:ssh_kexs, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyOptions, location_name: 'SshKexs', traits: {"smithy.api#documentation" => "<p>Lists the enabled SSH key exchange (KEX) encryption algorithms in the security policy that is attached to the server or connector. This parameter applies to both server and connector security policies.</p>"}))
    DescribedSecurityPolicy.add_member(:ssh_macs, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyOptions, location_name: 'SshMacs', traits: {"smithy.api#documentation" => "<p>Lists the enabled SSH message authentication code (MAC) encryption algorithms in the security policy that is attached to the server or connector. This parameter applies to both server and connector security policies.</p>"}))
    DescribedSecurityPolicy.add_member(:tls_ciphers, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyOptions, location_name: 'TlsCiphers', traits: {"smithy.api#documentation" => "<p>Lists the enabled Transport Layer Security (TLS) cipher encryption algorithms in the security policy that is attached to the server.</p> <note> <p>This parameter only applies to security policies for servers.</p> </note>"}))
    DescribedSecurityPolicy.add_member(:ssh_host_key_algorithms, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyOptions, location_name: 'SshHostKeyAlgorithms', traits: {"smithy.api#documentation" => "<p>Lists the host key algorithms for the security policy.</p> <note> <p>This parameter only applies to security policies for connectors.</p> </note>"}))
    DescribedSecurityPolicy.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyResourceType, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>The resource type to which the security policy applies, either server or connector.</p>"}))
    DescribedSecurityPolicy.add_member(:protocols, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyProtocols, location_name: 'Protocols', traits: {"smithy.api#documentation" => "<p>Lists the file transfer protocols that the security policy applies to.</p>"}))
    DescribedSecurityPolicy.type = Types::DescribedSecurityPolicy
    DescribedServer.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'Arn', traits: {"aws.cloudformation#cfnAdditionalIdentifier" => {}, "aws.cloudformation#cfnMutability" => "read", "smithy.api#documentation" => "<p>Specifies the unique Amazon Resource Name (ARN) of the server.</p>", "smithy.api#required" => {}}))
    DescribedServer.add_member(:certificate, Smithy::Schema::Shapes::ShapeRef.new(shape: Certificate, location_name: 'Certificate', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies the ARN of the Amazon Web ServicesCertificate Manager (ACM) certificate. Required when <code>Protocols</code> is set to <code>FTPS</code>.</p>"}))
    DescribedServer.add_member(:protocol_details, Smithy::Schema::Shapes::ShapeRef.new(shape: ProtocolDetails, location_name: 'ProtocolDetails', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>The protocol settings that are configured for your server.</p> <ul> <li> <p> To indicate passive mode (for FTP and FTPS protocols), use the <code>PassiveIp</code> parameter. Enter a single dotted-quad IPv4 address, such as the external IP address of a firewall, router, or load balancer. </p> </li> <li> <p>To ignore the error that is generated when the client attempts to use the <code>SETSTAT</code> command on a file that you are uploading to an Amazon S3 bucket, use the <code>SetStatOption</code> parameter. To have the Transfer Family server ignore the <code>SETSTAT</code> command and upload files without needing to make any changes to your SFTP client, set the value to <code>ENABLE_NO_OP</code>. If you set the <code>SetStatOption</code> parameter to <code>ENABLE_NO_OP</code>, Transfer Family generates a log entry to Amazon CloudWatch Logs, so that you can determine when the client is making a <code>SETSTAT</code> call.</p> </li> <li> <p>To determine whether your Transfer Family server resumes recent, negotiated sessions through a unique session ID, use the <code>TlsSessionResumptionMode</code> parameter.</p> </li> <li> <p> <code>As2Transports</code> indicates the transport method for the AS2 messages. Currently, only HTTP is supported.</p> </li> </ul>"}))
    DescribedServer.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: Domain, location_name: 'Domain', traits: {"aws.cloudformation#cfnMutability" => "create-and-read", "smithy.api#documentation" => "<p>Specifies the domain of the storage system that is used for file transfers. There are two domains available: Amazon Simple Storage Service (Amazon S3) and Amazon Elastic File System (Amazon EFS). The default value is S3.</p>"}))
    DescribedServer.add_member(:endpoint_details, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointDetails, location_name: 'EndpointDetails', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>The virtual private cloud (VPC) endpoint settings that are configured for your server. When you host your endpoint within your VPC, you can make your endpoint accessible only to resources within your VPC, or you can attach Elastic IP addresses and make your endpoint accessible to clients over the internet. Your VPC's default security groups are automatically assigned to your endpoint.</p>"}))
    DescribedServer.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointType, location_name: 'EndpointType', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Defines the type of endpoint that your server is connected to. If your server is connected to a VPC endpoint, your server isn't accessible over the public internet.</p>"}))
    DescribedServer.add_member(:host_key_fingerprint, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKeyFingerprint, location_name: 'HostKeyFingerprint', traits: {"aws.cloudformation#cfnExcludeProperty" => {}, "smithy.api#documentation" => "<p>Specifies the Base64-encoded SHA256 fingerprint of the server's host key. This value is equivalent to the output of the <code>ssh-keygen -l -f my-new-server-key</code> command.</p>"}))
    DescribedServer.add_member(:identity_provider_details, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentityProviderDetails, location_name: 'IdentityProviderDetails', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies information to call a customer-supplied authentication API. This field is not populated when the <code>IdentityProviderType</code> of a server is <code>AWS_DIRECTORY_SERVICE</code> or <code>SERVICE_MANAGED</code>.</p>"}))
    DescribedServer.add_member(:identity_provider_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentityProviderType, location_name: 'IdentityProviderType', traits: {"smithy.api#documentation" => "<p>The mode of authentication for a server. The default value is <code>SERVICE_MANAGED</code>, which allows you to store and access user credentials within the Transfer Family service.</p> <p>Use <code>AWS_DIRECTORY_SERVICE</code> to provide access to Active Directory groups in Directory Service for Microsoft Active Directory or Microsoft Active Directory in your on-premises environment or in Amazon Web Services using AD Connector. This option also requires you to provide a Directory ID by using the <code>IdentityProviderDetails</code> parameter.</p> <p>Use the <code>API_GATEWAY</code> value to integrate with an identity provider of your choosing. The <code>API_GATEWAY</code> setting requires you to provide an Amazon API Gateway endpoint URL to call for authentication by using the <code>IdentityProviderDetails</code> parameter.</p> <p>Use the <code>AWS_LAMBDA</code> value to directly use an Lambda function as your identity provider. If you choose this value, you must specify the ARN for the Lambda function in the <code>Function</code> parameter for the <code>IdentityProviderDetails</code> data type.</p>"}))
    DescribedServer.add_member(:logging_role, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableRole, location_name: 'LoggingRole', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that allows a server to turn on Amazon CloudWatch logging for Amazon S3 or Amazon EFS events. When set, you can view user activity in your CloudWatch logs.</p>"}))
    DescribedServer.add_member(:post_authentication_login_banner, Smithy::Schema::Shapes::ShapeRef.new(shape: PostAuthenticationLoginBanner, location_name: 'PostAuthenticationLoginBanner', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies a string to display when users connect to a server. This string is displayed after the user authenticates.</p> <note> <p>The SFTP protocol does not support post-authentication display banners.</p> </note>"}))
    DescribedServer.add_member(:pre_authentication_login_banner, Smithy::Schema::Shapes::ShapeRef.new(shape: PreAuthenticationLoginBanner, location_name: 'PreAuthenticationLoginBanner', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies a string to display when users connect to a server. This string is displayed before the user authenticates. For example, the following banner displays details about using the system:</p> <p> <code>This system is for the use of authorized users only. Individuals using this computer system without authority, or in excess of their authority, are subject to having all of their activities on this system monitored and recorded by system personnel.</code> </p>"}))
    DescribedServer.add_member(:protocols, Smithy::Schema::Shapes::ShapeRef.new(shape: Protocols, location_name: 'Protocols', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies the file transfer protocol or protocols over which your file transfer protocol client can connect to your server's endpoint. The available protocols are:</p> <ul> <li> <p> <code>SFTP</code> (Secure Shell (SSH) File Transfer Protocol): File transfer over SSH</p> </li> <li> <p> <code>FTPS</code> (File Transfer Protocol Secure): File transfer with TLS encryption</p> </li> <li> <p> <code>FTP</code> (File Transfer Protocol): Unencrypted file transfer</p> </li> <li> <p> <code>AS2</code> (Applicability Statement 2): used for transporting structured business-to-business data</p> </li> </ul> <note> <ul> <li> <p>If you select <code>FTPS</code>, you must choose a certificate stored in Certificate Manager (ACM) which is used to identify your server when clients connect to it over FTPS.</p> </li> <li> <p>If <code>Protocol</code> includes either <code>FTP</code> or <code>FTPS</code>, then the <code>EndpointType</code> must be <code>VPC</code> and the <code>IdentityProviderType</code> must be either <code>AWS_DIRECTORY_SERVICE</code>, <code>AWS_LAMBDA</code>, or <code>API_GATEWAY</code>.</p> </li> <li> <p>If <code>Protocol</code> includes <code>FTP</code>, then <code>AddressAllocationIds</code> cannot be associated.</p> </li> <li> <p>If <code>Protocol</code> is set only to <code>SFTP</code>, the <code>EndpointType</code> can be set to <code>PUBLIC</code> and the <code>IdentityProviderType</code> can be set any of the supported identity types: <code>SERVICE_MANAGED</code>, <code>AWS_DIRECTORY_SERVICE</code>, <code>AWS_LAMBDA</code>, or <code>API_GATEWAY</code>.</p> </li> <li> <p>If <code>Protocol</code> includes <code>AS2</code>, then the <code>EndpointType</code> must be <code>VPC</code>, and domain must be Amazon S3.</p> </li> </ul> </note>"}))
    DescribedServer.add_member(:security_policy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyName, location_name: 'SecurityPolicyName', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies the name of the security policy for the server.</p>"}))
    DescribedServer.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>Specifies the unique system-assigned identifier for a server that you instantiate.</p>"}))
    DescribedServer.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: State, location_name: 'State', traits: {"aws.cloudformation#cfnExcludeProperty" => {}, "smithy.api#documentation" => "<p>The condition of the server that was described. A value of <code>ONLINE</code> indicates that the server can accept jobs and transfer files. A <code>State</code> value of <code>OFFLINE</code> means that the server cannot perform file transfer operations.</p> <p>The states of <code>STARTING</code> and <code>STOPPING</code> indicate that the server is in an intermediate state, either not fully able to respond, or not fully offline. The values of <code>START_FAILED</code> or <code>STOP_FAILED</code> can indicate an error condition.</p>"}))
    DescribedServer.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies the key-value pairs that you can use to search for and group servers that were assigned to the server that was described.</p>"}))
    DescribedServer.add_member(:user_count, Smithy::Schema::Shapes::ShapeRef.new(shape: UserCount, location_name: 'UserCount', traits: {"aws.cloudformation#cfnExcludeProperty" => {}, "smithy.api#documentation" => "<p>Specifies the number of users that are assigned to a server you specified with the <code>ServerId</code>.</p>"}))
    DescribedServer.add_member(:workflow_details, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkflowDetails, location_name: 'WorkflowDetails', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies the workflow ID for the workflow to assign and the execution role that's used for executing the workflow.</p> <p>In addition to a workflow to execute when a file is uploaded completely, <code>WorkflowDetails</code> can also contain a workflow ID (and execution role) for a workflow to execute on partial upload. A partial upload occurs when the server session disconnects while the file is still being uploaded.</p>"}))
    DescribedServer.add_member(:structured_log_destinations, Smithy::Schema::Shapes::ShapeRef.new(shape: StructuredLogDestinations, location_name: 'StructuredLogDestinations', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies the log groups to which your server logs are sent.</p> <p>To specify a log group, you must provide the ARN for an existing log group. In this case, the format of the log group is as follows:</p> <p> <code>arn:aws:logs:region-name:amazon-account-id:log-group:log-group-name:*</code> </p> <p>For example, <code>arn:aws:logs:us-east-1:111122223333:log-group:mytestgroup:*</code> </p> <p>If you have previously specified a log group for a server, you can clear it, and in effect turn off structured logging, by providing an empty value for this parameter in an <code>update-server</code> call. For example:</p> <p> <code>update-server --server-id s-1234567890abcdef0 --structured-log-destinations</code> </p>"}))
    DescribedServer.add_member(:s3_storage_options, Smithy::Schema::Shapes::ShapeRef.new(shape: S3StorageOptions, location_name: 'S3StorageOptions', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies whether or not performance for your Amazon S3 directories is optimized. This is disabled by default.</p> <p>By default, home directory mappings have a <code>TYPE</code> of <code>DIRECTORY</code>. If you enable this option, you would then need to explicitly set the <code>HomeDirectoryMapEntry</code> <code>Type</code> to <code>FILE</code> if you want a mapping to have a file target.</p>"}))
    DescribedServer.add_member(:as2_service_managed_egress_ip_addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceManagedEgressIpAddresses, location_name: 'As2ServiceManagedEgressIpAddresses', traits: {"aws.cloudformation#cfnMutability" => "read", "smithy.api#documentation" => "<p>The list of egress IP addresses of this server. These IP addresses are only relevant for servers that use the AS2 protocol. They are used for sending asynchronous MDNs.</p> <p>These IP addresses are assigned automatically when you create an AS2 server. Additionally, if you update an existing server and add the AS2 protocol, static IP addresses are assigned as well.</p>"}))
    DescribedServer.add_member(:ip_address_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddressType, location_name: 'IpAddressType', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies whether to use IPv4 only, or to use dual-stack (IPv4 and IPv6) for your Transfer Family endpoint. The default value is <code>IPV4</code>.</p> <important> <p>The <code>IpAddressType</code> parameter has the following limitations:</p> <ul> <li> <p>It cannot be changed while the server is online. You must stop the server before modifying this parameter.</p> </li> <li> <p>It cannot be updated to <code>DUALSTACK</code> if the server has <code>AddressAllocationIds</code> specified.</p> </li> </ul> </important> <note> <p>When using <code>DUALSTACK</code> as the <code>IpAddressType</code>, you cannot set the <code>AddressAllocationIds</code> parameter for the <a href=\"https://docs.aws.amazon.com/transfer/latest/APIReference/API_EndpointDetails.html\">EndpointDetails</a> for the server.</p> </note>"}))
    DescribedServer.type = Types::DescribedServer
    DescribedUser.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'Arn', traits: {"aws.cloudformation#cfnAdditionalIdentifier" => {}, "aws.cloudformation#cfnMutability" => "read", "smithy.api#documentation" => "<p>Specifies the unique Amazon Resource Name (ARN) for the user that was requested to be described.</p>", "smithy.api#required" => {}}))
    DescribedUser.add_member(:home_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'HomeDirectory', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>The landing directory (folder) for a user when they log in to the server using the client.</p> <p>A <code>HomeDirectory</code> example is <code>/bucket_name/home/mydirectory</code>.</p> <note> <p>You can use the <code>HomeDirectory</code> parameter for <code>HomeDirectoryType</code> when it is set to either <code>PATH</code> or <code>LOGICAL</code>.</p> </note>"}))
    DescribedUser.add_member(:home_directory_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryMappings, location_name: 'HomeDirectoryMappings', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Logical directory mappings that specify what Amazon S3 or Amazon EFS paths and keys should be visible to your user and how you want to make them visible. You must specify the <code>Entry</code> and <code>Target</code> pair, where <code>Entry</code> shows how the path is made visible and <code>Target</code> is the actual Amazon S3 or Amazon EFS path. If you only specify a target, it is displayed as is. You also must ensure that your Identity and Access Management (IAM) role provides access to paths in <code>Target</code>. This value can be set only when <code>HomeDirectoryType</code> is set to <i>LOGICAL</i>.</p> <p>In most cases, you can use this value instead of the session policy to lock your user down to the designated home directory (\"<code>chroot</code>\"). To do this, you can set <code>Entry</code> to '/' and set <code>Target</code> to the HomeDirectory parameter value.</p>"}))
    DescribedUser.add_member(:home_directory_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryType, location_name: 'HomeDirectoryType', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>The type of landing directory (folder) that you want your users' home directory to be when they log in to the server. If you set it to <code>PATH</code>, the user will see the absolute Amazon S3 bucket or Amazon EFS path as is in their file transfer protocol clients. If you set it to <code>LOGICAL</code>, you need to provide mappings in the <code>HomeDirectoryMappings</code> for how you want to make Amazon S3 or Amazon EFS paths visible to your users.</p> <note> <p>If <code>HomeDirectoryType</code> is <code>LOGICAL</code>, you must provide mappings, using the <code>HomeDirectoryMappings</code> parameter. If, on the other hand, <code>HomeDirectoryType</code> is <code>PATH</code>, you provide an absolute path using the <code>HomeDirectory</code> parameter. You cannot have both <code>HomeDirectory</code> and <code>HomeDirectoryMappings</code> in your template.</p> </note>"}))
    DescribedUser.add_member(:policy, Smithy::Schema::Shapes::ShapeRef.new(shape: Policy, location_name: 'Policy', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>A session policy for your user so that you can use the same Identity and Access Management (IAM) role across multiple users. This policy scopes down a user's access to portions of their Amazon S3 bucket. Variables that you can use inside this policy include <code>${Transfer:UserName}</code>, <code>${Transfer:HomeDirectory}</code>, and <code>${Transfer:HomeBucket}</code>.</p>"}))
    DescribedUser.add_member(:posix_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: PosixProfile, location_name: 'PosixProfile', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies the full POSIX identity, including user ID (<code>Uid</code>), group ID (<code>Gid</code>), and any secondary groups IDs (<code>SecondaryGids</code>), that controls your users' access to your Amazon Elastic File System (Amazon EFS) file systems. The POSIX permissions that are set on files and directories in your file system determine the level of access your users get when transferring files into and out of your Amazon EFS file systems.</p>"}))
    DescribedUser.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'Role', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that controls your users' access to your Amazon S3 bucket or Amazon EFS file system. The policies attached to this role determine the level of access that you want to provide your users when transferring files into and out of your Amazon S3 bucket or Amazon EFS file system. The IAM role should also contain a trust relationship that allows the server to access your resources when servicing your users' transfer requests.</p>"}))
    DescribedUser.add_member(:ssh_public_keys, Smithy::Schema::Shapes::ShapeRef.new(shape: SshPublicKeys, location_name: 'SshPublicKeys', traits: {"aws.cloudformation#cfnExcludeProperty" => {}, "smithy.api#documentation" => "<p>Specifies the public key portion of the Secure Shell (SSH) keys stored for the described user.</p> <note> <p>To delete the public key body, set its value to zero keys, as shown here:</p> <p> <code>SshPublicKeys: []</code> </p> </note>"}))
    DescribedUser.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"aws.cloudformation#cfnMutability" => "full", "smithy.api#documentation" => "<p>Specifies the key-value pairs for the user requested. Tag can be used to search for and group users for a variety of purposes.</p>"}))
    DescribedUser.add_member(:user_name, Smithy::Schema::Shapes::ShapeRef.new(shape: UserName, location_name: 'UserName', traits: {"smithy.api#documentation" => "<p>Specifies the name of the user that was requested to be described. User names are used for authentication purposes. This is the string that will be used by your user when they log in to your server.</p>"}))
    DescribedUser.type = Types::DescribedUser
    DescribedWebApp.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the web app.</p>", "smithy.api#required" => {}}))
    DescribedWebApp.add_member(:web_app_id, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppId, location_name: 'WebAppId', traits: {"smithy.api#documentation" => "<p>The unique identifier for the web app.</p>", "smithy.api#required" => {}}))
    DescribedWebApp.add_member(:described_identity_provider_details, Smithy::Schema::Shapes::ShapeRef.new(shape: DescribedWebAppIdentityProviderDetails, location_name: 'DescribedIdentityProviderDetails', traits: {"smithy.api#documentation" => "<p>A structure that contains the details for the identity provider used by the web app.</p>"}))
    DescribedWebApp.add_member(:access_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppAccessEndpoint, location_name: 'AccessEndpoint', traits: {"smithy.api#documentation" => "<p>The <code>AccessEndpoint</code> is the URL that you provide to your users for them to interact with the Transfer Family web app. You can specify a custom URL or use the default value.</p>"}))
    DescribedWebApp.add_member(:web_app_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppEndpoint, location_name: 'WebAppEndpoint', traits: {"smithy.api#documentation" => "<p>The <code>WebAppEndpoint</code> is the unique URL for your Transfer Family web app. This is the value that you use when you configure <b>Origins</b> on CloudFront.</p>"}))
    DescribedWebApp.add_member(:web_app_units, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppUnits, location_name: 'WebAppUnits', traits: {"smithy.api#documentation" => "<p>A union that contains the value for number of concurrent connections or the user sessions on your web app.</p>"}))
    DescribedWebApp.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Key-value pairs that can be used to group and search for web apps. Tags are metadata attached to web apps for any purpose.</p>"}))
    DescribedWebApp.add_member(:web_app_endpoint_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppEndpointPolicy, location_name: 'WebAppEndpointPolicy', traits: {"smithy.api#documentation" => "<p> Setting for the type of endpoint policy for the web app. The default value is <code>STANDARD</code>. </p> <p>If your web app was created in an Amazon Web Services GovCloud (US) Region, the value of this parameter can be <code>FIPS</code>, which indicates the web app endpoint is FIPS-compliant.</p>"}))
    DescribedWebApp.type = Types::DescribedWebApp
    DescribedWebAppCustomization.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>Returns the Amazon Resource Name (ARN) for the web app.</p>", "smithy.api#required" => {}}))
    DescribedWebAppCustomization.add_member(:web_app_id, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppId, location_name: 'WebAppId', traits: {"smithy.api#documentation" => "<p>Returns the unique identifier for your web app.</p>", "smithy.api#required" => {}}))
    DescribedWebAppCustomization.add_member(:title, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppTitle, location_name: 'Title', traits: {"smithy.api#documentation" => "<p>Returns the page title that you defined for your web app.</p>"}))
    DescribedWebAppCustomization.add_member(:logo_file, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppLogoFile, location_name: 'LogoFile', traits: {"smithy.api#documentation" => "<p>Returns a logo file data string (in base64 encoding).</p>"}))
    DescribedWebAppCustomization.add_member(:favicon_file, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAppFaviconFile, location_name: 'FaviconFile', traits: {"smithy.api#documentation" => "<p>Returns an icon file data string (in base64 encoding).</p>"}))
    DescribedWebAppCustomization.type = Types::DescribedWebAppCustomization
    DescribedWebAppIdentityProviderDetails.add_member(:identity_center_config, Types::DescribedWebAppIdentityProviderDetails::IdentityCenterConfig, Smithy::Schema::Shapes::ShapeRef.new(shape: DescribedIdentityCenterConfig, location_name: 'IdentityCenterConfig', traits: {"smithy.api#documentation" => "<p>Returns a structure for your identity provider details. This structure contains the instance ARN and role being used for the web app.</p>"}))
    DescribedWebAppIdentityProviderDetails.add_member(:unknown, Types::DescribedWebAppIdentityProviderDetails::Unknown, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit))
    DescribedWebAppIdentityProviderDetails.type = Types::DescribedWebAppIdentityProviderDetails
