    ImportCertificateRequest.add_member(:certificate, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateBodyType, location_name: 'Certificate', traits: {"smithy.api#documentation" => "<ul> <li> <p>For the CLI, provide a file path for a certificate in URI format. For example, <code>--certificate file://encryption-cert.pem</code>. Alternatively, you can provide the raw content.</p> </li> <li> <p>For the SDK, specify the raw content of a certificate file. For example, <code>--certificate \"`cat encryption-cert.pem`\"</code>.</p> </li> </ul> <note> <p>You can provide both the certificate and its chain in this parameter, without needing to use the <code>CertificateChain</code> parameter. If you use this parameter for both the certificate and its chain, do not use the <code>CertificateChain</code> parameter.</p> </note>", "smithy.api#required" => {}}))
