    ListedProfile.add_member(:as2_id, Smithy::Schema::Shapes::ShapeRef.new(shape: As2Id, location_name: 'As2Id', traits: {"smithy.api#documentation" => "<p>The <code>As2Id</code> is the <i>AS2-name</i>, as defined in the <a href=\"https://datatracker.ietf.org/doc/html/rfc4130\">RFC 4130</a>. For inbound transfers, this is the <code>AS2-From</code> header for the AS2 messages sent from the partner. For outbound connectors, this is the <code>AS2-To</code> header for the AS2 messages sent to the partner using the <code>StartFileTransfer</code> API operation. This ID cannot include spaces.</p>"}))
