    ListedServer.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: Domain, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>Specifies the domain of the storage system that is used for file transfers. There are two domains available: Amazon Simple Storage Service (Amazon S3) and Amazon Elastic File System (Amazon EFS). The default value is S3.</p>"}))
    ListedServer.add_member(:identity_provider_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentityProviderType, location_name: 'IdentityProviderType', traits: {"smithy.api#documentation" => "<p>The mode of authentication for a server. The default value is <code>SERVICE_MANAGED</code>, which allows you to store and access user credentials within the Transfer Family service.</p> <p>Use <code>AWS_DIRECTORY_SERVICE</code> to provide access to Active Directory groups in Directory Service for Microsoft Active Directory or Microsoft Active Directory in your on-premises environment or in Amazon Web Services using AD Connector. This option also requires you to provide a Directory ID by using the <code>IdentityProviderDetails</code> parameter.</p> <p>Use the <code>API_GATEWAY</code> value to integrate with an identity provider of your choosing. The <code>API_GATEWAY</code> setting requires you to provide an Amazon API Gateway endpoint URL to call for authentication by using the <code>IdentityProviderDetails</code> parameter.</p> <p>Use the <code>AWS_LAMBDA</code> value to directly use an Lambda function as your identity provider. If you choose this value, you must specify the ARN for the Lambda function in the <code>Function</code> parameter for the <code>IdentityProviderDetails</code> data type.</p>"}))
    ListedServer.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointType, location_name: 'EndpointType', traits: {"smithy.api#documentation" => "<p>Specifies the type of VPC endpoint that your server is connected to. If your server is connected to a VPC endpoint, your server isn't accessible over the public internet.</p>"}))
    ListedServer.add_member(:logging_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'LoggingRole', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that allows a server to turn on Amazon CloudWatch logging for Amazon S3 or Amazon EFS events. When set, you can view user activity in your CloudWatch logs.</p>"}))
    ListedServer.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>Specifies the unique system assigned identifier for the servers that were listed.</p>"}))
    ListedServer.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: State, location_name: 'State', traits: {"smithy.api#documentation" => "<p>The condition of the server that was described. A value of <code>ONLINE</code> indicates that the server can accept jobs and transfer files. A <code>State</code> value of <code>OFFLINE</code> means that the server cannot perform file transfer operations.</p> <p>The states of <code>STARTING</code> and <code>STOPPING</code> indicate that the server is in an intermediate state, either not fully able to respond, or not fully offline. The values of <code>START_FAILED</code> or <code>STOP_FAILED</code> can indicate an error condition.</p>"}))
