    UpdateAccessResponse.type = Types::UpdateAccessResponse
    UpdateAgreementRequest.add_member(:agreement_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AgreementId, location_name: 'AgreementId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the agreement. This identifier is returned when you create an agreement.</p>", "smithy.api#required" => {}}))
