    UpdateAgreementRequest.add_member(:local_profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'LocalProfileId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the AS2 local profile.</p> <p>To change the local profile identifier, provide a new value here.</p>"}))
    UpdateAgreementRequest.add_member(:partner_profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'PartnerProfileId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the partner profile. To change the partner profile identifier, provide a new value here.</p>"}))
    UpdateAgreementRequest.add_member(:base_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'BaseDirectory', traits: {"smithy.api#documentation" => "<p>To change the landing directory (folder) for files that are transferred, provide the bucket folder that you want to use; for example, <code>/<i>amzn-s3-demo-bucket</i>/<i>home</i>/<i>mydirectory</i> </code>.</p>"}))
    UpdateAgreementRequest.add_member(:access_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'AccessRole', traits: {"smithy.api#documentation" => "<p>Connectors are used to send files using either the AS2 or SFTP protocol. For the access role, provide the Amazon Resource Name (ARN) of the Identity and Access Management role to use.</p> <p> <b>For AS2 connectors</b> </p> <p>With AS2, you can send files by calling <code>StartFileTransfer</code> and specifying the file paths in the request parameter, <code>SendFilePaths</code>. We use the file’s parent directory (for example, for <code>--send-file-paths /bucket/dir/file.txt</code>, parent directory is <code>/bucket/dir/</code>) to temporarily store a processed AS2 message file, store the MDN when we receive them from the partner, and write a final JSON file containing relevant metadata of the transmission. So, the <code>AccessRole</code> needs to provide read and write access to the parent directory of the file location used in the <code>StartFileTransfer</code> request. Additionally, you need to provide read and write access to the parent directory of the files that you intend to send with <code>StartFileTransfer</code>.</p> <p>If you are using Basic authentication for your AS2 connector, the access role requires the <code>secretsmanager:GetSecretValue</code> permission for the secret. If the secret is encrypted using a customer-managed key instead of the Amazon Web Services managed key in Secrets Manager, then the role also needs the <code>kms:Decrypt</code> permission for that key.</p> <p> <b>For SFTP connectors</b> </p> <p>Make sure that the access role provides read and write access to the parent directory of the file location that's used in the <code>StartFileTransfer</code> request. Additionally, make sure that the role provides <code>secretsmanager:GetSecretValue</code> permission to Secrets Manager.</p>"}))
    UpdateAgreementRequest.add_member(:preserve_filename, Smithy::Schema::Shapes::ShapeRef.new(shape: PreserveFilenameType, location_name: 'PreserveFilename', traits: {"smithy.api#documentation" => "<p> Determines whether or not Transfer Family appends a unique string of characters to the end of the AS2 message payload filename when saving it. </p> <ul> <li> <p> <code>ENABLED</code>: the filename provided by your trading parter is preserved when the file is saved.</p> </li> <li> <p> <code>DISABLED</code> (default value): when Transfer Family saves the file, the filename is adjusted, as described in <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/send-as2-messages.html#file-names-as2\">File names and locations</a>.</p> </li> </ul>"}))
    UpdateAgreementRequest.add_member(:enforce_message_signing, Smithy::Schema::Shapes::ShapeRef.new(shape: EnforceMessageSigningType, location_name: 'EnforceMessageSigning', traits: {"smithy.api#documentation" => "<p> Determines whether or not unsigned messages from your trading partners will be accepted. </p> <ul> <li> <p> <code>ENABLED</code>: Transfer Family rejects unsigned messages from your trading partner.</p> </li> <li> <p> <code>DISABLED</code> (default value): Transfer Family accepts unsigned messages from your trading partner.</p> </li> </ul>"}))
    UpdateAgreementRequest.add_member(:custom_directories, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomDirectoriesType, location_name: 'CustomDirectories', traits: {"smithy.api#documentation" => "<p>A <code>CustomDirectoriesType</code> structure. This structure specifies custom directories for storing various AS2 message files. You can specify directories for the following types of files.</p> <ul> <li> <p>Failed files</p> </li> <li> <p>MDN files</p> </li> <li> <p>Payload files</p> </li> <li> <p>Status files</p> </li> <li> <p>Temporary files</p> </li> </ul>"}))
    UpdateAgreementRequest.type = Types::UpdateAgreementRequest
    UpdateAgreementResponse.add_member(:agreement_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AgreementId, location_name: 'AgreementId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the agreement. This identifier is returned when you create an agreement.</p>", "smithy.api#required" => {}}))
    UpdateAgreementResponse.type = Types::UpdateAgreementResponse
    UpdateCertificateRequest.add_member(:certificate_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateId, location_name: 'CertificateId', traits: {"smithy.api#documentation" => "<p>The identifier of the certificate object that you are updating.</p>", "smithy.api#required" => {}}))
    UpdateCertificateRequest.add_member(:active_date, Smithy::Schema::Shapes::ShapeRef.new(shape: CertDate, location_name: 'ActiveDate', traits: {"smithy.api#documentation" => "<p>An optional date that specifies when the certificate becomes active. If you do not specify a value, <code>ActiveDate</code> takes the same value as <code>NotBeforeDate</code>, which is specified by the CA. </p>"}))
    UpdateCertificateRequest.add_member(:inactive_date, Smithy::Schema::Shapes::ShapeRef.new(shape: CertDate, location_name: 'InactiveDate', traits: {"smithy.api#documentation" => "<p>An optional date that specifies when the certificate becomes inactive. If you do not specify a value, <code>InactiveDate</code> takes the same value as <code>NotAfterDate</code>, which is specified by the CA.</p>"}))
    UpdateCertificateRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A short description to help identify the certificate.</p>"}))
    UpdateCertificateRequest.type = Types::UpdateCertificateRequest
    UpdateCertificateResponse.add_member(:certificate_id, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateId, location_name: 'CertificateId', traits: {"smithy.api#documentation" => "<p>Returns the identifier of the certificate object that you are updating.</p>", "smithy.api#required" => {}}))
    UpdateCertificateResponse.type = Types::UpdateCertificateResponse
    UpdateConnectorRequest.add_member(:connector_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectorId, location_name: 'ConnectorId', traits: {"smithy.api#documentation" => "<p>The unique identifier for the connector.</p>", "smithy.api#required" => {}}))
    UpdateConnectorRequest.add_member(:url, Smithy::Schema::Shapes::ShapeRef.new(shape: Url, location_name: 'Url', traits: {"smithy.api#documentation" => "<p>The URL of the partner's AS2 or SFTP endpoint.</p>"}))
    UpdateConnectorRequest.add_member(:as2_config, Smithy::Schema::Shapes::ShapeRef.new(shape: As2ConnectorConfig, location_name: 'As2Config', traits: {"smithy.api#documentation" => "<p>A structure that contains the parameters for an AS2 connector object.</p>"}))
    UpdateConnectorRequest.add_member(:access_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'AccessRole', traits: {"smithy.api#documentation" => "<p>Connectors are used to send files using either the AS2 or SFTP protocol. For the access role, provide the Amazon Resource Name (ARN) of the Identity and Access Management role to use.</p> <p> <b>For AS2 connectors</b> </p> <p>With AS2, you can send files by calling <code>StartFileTransfer</code> and specifying the file paths in the request parameter, <code>SendFilePaths</code>. We use the file’s parent directory (for example, for <code>--send-file-paths /bucket/dir/file.txt</code>, parent directory is <code>/bucket/dir/</code>) to temporarily store a processed AS2 message file, store the MDN when we receive them from the partner, and write a final JSON file containing relevant metadata of the transmission. So, the <code>AccessRole</code> needs to provide read and write access to the parent directory of the file location used in the <code>StartFileTransfer</code> request. Additionally, you need to provide read and write access to the parent directory of the files that you intend to send with <code>StartFileTransfer</code>.</p> <p>If you are using Basic authentication for your AS2 connector, the access role requires the <code>secretsmanager:GetSecretValue</code> permission for the secret. If the secret is encrypted using a customer-managed key instead of the Amazon Web Services managed key in Secrets Manager, then the role also needs the <code>kms:Decrypt</code> permission for that key.</p> <p> <b>For SFTP connectors</b> </p> <p>Make sure that the access role provides read and write access to the parent directory of the file location that's used in the <code>StartFileTransfer</code> request. Additionally, make sure that the role provides <code>secretsmanager:GetSecretValue</code> permission to Secrets Manager.</p>"}))
    UpdateConnectorRequest.add_member(:logging_role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'LoggingRole', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that allows a connector to turn on CloudWatch logging for Amazon S3 events. When set, you can view connector activity in your CloudWatch logs.</p>"}))
    UpdateConnectorRequest.add_member(:sftp_config, Smithy::Schema::Shapes::ShapeRef.new(shape: SftpConnectorConfig, location_name: 'SftpConfig', traits: {"smithy.api#documentation" => "<p>A structure that contains the parameters for an SFTP connector object.</p>"}))
    UpdateConnectorRequest.add_member(:security_policy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectorSecurityPolicyName, location_name: 'SecurityPolicyName', traits: {"smithy.api#documentation" => "<p>Specifies the name of the security policy for the connector.</p>"}))
    UpdateConnectorRequest.type = Types::UpdateConnectorRequest
    UpdateConnectorResponse.add_member(:connector_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectorId, location_name: 'ConnectorId', traits: {"smithy.api#documentation" => "<p>Returns the identifier of the connector object that you are updating.</p>", "smithy.api#required" => {}}))
    UpdateConnectorResponse.type = Types::UpdateConnectorResponse
    UpdateHostKeyRequest.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>The identifier of the server that contains the host key that you are updating.</p>", "smithy.api#required" => {}}))
    UpdateHostKeyRequest.add_member(:host_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKeyId, location_name: 'HostKeyId', traits: {"smithy.api#documentation" => "<p>The identifier of the host key that you are updating.</p>", "smithy.api#required" => {}}))
    UpdateHostKeyRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKeyDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>An updated description for the host key.</p>", "smithy.api#required" => {}}))
    UpdateHostKeyRequest.type = Types::UpdateHostKeyRequest
    UpdateHostKeyResponse.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>Returns the server identifier for the server that contains the updated host key.</p>", "smithy.api#required" => {}}))
    UpdateHostKeyResponse.add_member(:host_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKeyId, location_name: 'HostKeyId', traits: {"smithy.api#documentation" => "<p>Returns the host key identifier for the updated host key.</p>", "smithy.api#required" => {}}))
    UpdateHostKeyResponse.type = Types::UpdateHostKeyResponse
    UpdateProfileRequest.add_member(:profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'ProfileId', traits: {"smithy.api#documentation" => "<p>The identifier of the profile object that you are updating.</p>", "smithy.api#required" => {}}))
    UpdateProfileRequest.add_member(:certificate_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateIds, location_name: 'CertificateIds', traits: {"smithy.api#documentation" => "<p>An array of identifiers for the imported certificates. You use this identifier for working with profiles and partner profiles.</p>"}))
    UpdateProfileRequest.type = Types::UpdateProfileRequest
    UpdateProfileResponse.add_member(:profile_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfileId, location_name: 'ProfileId', traits: {"smithy.api#documentation" => "<p>Returns the identifier for the profile that's being updated.</p>", "smithy.api#required" => {}}))
    UpdateProfileResponse.type = Types::UpdateProfileResponse
    UpdateServerRequest.add_member(:certificate, Smithy::Schema::Shapes::ShapeRef.new(shape: Certificate, location_name: 'Certificate', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon Web ServicesCertificate Manager (ACM) certificate. Required when <code>Protocols</code> is set to <code>FTPS</code>.</p> <p>To request a new public certificate, see <a href=\"https://docs.aws.amazon.com/acm/latest/userguide/gs-acm-request-public.html\">Request a public certificate</a> in the <i> Amazon Web ServicesCertificate Manager User Guide</i>.</p> <p>To import an existing certificate into ACM, see <a href=\"https://docs.aws.amazon.com/acm/latest/userguide/import-certificate.html\">Importing certificates into ACM</a> in the <i> Amazon Web ServicesCertificate Manager User Guide</i>.</p> <p>To request a private certificate to use FTPS through private IP addresses, see <a href=\"https://docs.aws.amazon.com/acm/latest/userguide/gs-acm-request-private.html\">Request a private certificate</a> in the <i> Amazon Web ServicesCertificate Manager User Guide</i>.</p> <p>Certificates with the following cryptographic algorithms and key sizes are supported:</p> <ul> <li> <p>2048-bit RSA (RSA_2048)</p> </li> <li> <p>4096-bit RSA (RSA_4096)</p> </li> <li> <p>Elliptic Prime Curve 256 bit (EC_prime256v1)</p> </li> <li> <p>Elliptic Prime Curve 384 bit (EC_secp384r1)</p> </li> <li> <p>Elliptic Prime Curve 521 bit (EC_secp521r1)</p> </li> </ul> <note> <p>The certificate must be a valid SSL/TLS X.509 version 3 certificate with FQDN or IP address specified and information about the issuer.</p> </note>"}))
    UpdateServerRequest.add_member(:protocol_details, Smithy::Schema::Shapes::ShapeRef.new(shape: ProtocolDetails, location_name: 'ProtocolDetails', traits: {"smithy.api#documentation" => "<p>The protocol settings that are configured for your server.</p> <ul> <li> <p> To indicate passive mode (for FTP and FTPS protocols), use the <code>PassiveIp</code> parameter. Enter a single dotted-quad IPv4 address, such as the external IP address of a firewall, router, or load balancer. </p> </li> <li> <p>To ignore the error that is generated when the client attempts to use the <code>SETSTAT</code> command on a file that you are uploading to an Amazon S3 bucket, use the <code>SetStatOption</code> parameter. To have the Transfer Family server ignore the <code>SETSTAT</code> command and upload files without needing to make any changes to your SFTP client, set the value to <code>ENABLE_NO_OP</code>. If you set the <code>SetStatOption</code> parameter to <code>ENABLE_NO_OP</code>, Transfer Family generates a log entry to Amazon CloudWatch Logs, so that you can determine when the client is making a <code>SETSTAT</code> call.</p> </li> <li> <p>To determine whether your Transfer Family server resumes recent, negotiated sessions through a unique session ID, use the <code>TlsSessionResumptionMode</code> parameter.</p> </li> <li> <p> <code>As2Transports</code> indicates the transport method for the AS2 messages. Currently, only HTTP is supported.</p> </li> </ul>"}))
    UpdateServerRequest.add_member(:endpoint_details, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointDetails, location_name: 'EndpointDetails', traits: {"smithy.api#documentation" => "<p>The virtual private cloud (VPC) endpoint settings that are configured for your server. When you host your endpoint within your VPC, you can make your endpoint accessible only to resources within your VPC, or you can attach Elastic IP addresses and make your endpoint accessible to clients over the internet. Your VPC's default security groups are automatically assigned to your endpoint.</p>"}))
    UpdateServerRequest.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointType, location_name: 'EndpointType', traits: {"smithy.api#documentation" => "<p>The type of endpoint that you want your server to use. You can choose to make your server's endpoint publicly accessible (PUBLIC) or host it inside your VPC. With an endpoint that is hosted in a VPC, you can restrict access to your server and resources only within your VPC or choose to make it internet facing by attaching Elastic IP addresses directly to it.</p> <note> <p> After May 19, 2021, you won't be able to create a server using <code>EndpointType=VPC_ENDPOINT</code> in your Amazon Web Services account if your account hasn't already done so before May 19, 2021. If you have already created servers with <code>EndpointType=VPC_ENDPOINT</code> in your Amazon Web Services account on or before May 19, 2021, you will not be affected. After this date, use <code>EndpointType</code>=<code>VPC</code>.</p> <p>For more information, see https://docs.aws.amazon.com/transfer/latest/userguide/create-server-in-vpc.html#deprecate-vpc-endpoint.</p> <p>It is recommended that you use <code>VPC</code> as the <code>EndpointType</code>. With this endpoint type, you have the option to directly associate up to three Elastic IPv4 addresses (BYO IP included) with your server's endpoint and use VPC security groups to restrict traffic by the client's public IP address. This is not possible with <code>EndpointType</code> set to <code>VPC_ENDPOINT</code>.</p> </note>"}))
    UpdateServerRequest.add_member(:host_key, Smithy::Schema::Shapes::ShapeRef.new(shape: HostKey, location_name: 'HostKey', traits: {"aws.cloudformation#cfnExcludeProperty" => {}, "smithy.api#documentation" => "<p>The RSA, ECDSA, or ED25519 private key to use for your SFTP-enabled server. You can add multiple host keys, in case you want to rotate keys, or have a set of active keys that use different algorithms.</p> <p>Use the following command to generate an RSA 2048 bit key with no passphrase:</p> <p> <code>ssh-keygen -t rsa -b 2048 -N \"\" -m PEM -f my-new-server-key</code>.</p> <p>Use a minimum value of 2048 for the <code>-b</code> option. You can create a stronger key by using 3072 or 4096.</p> <p>Use the following command to generate an ECDSA 256 bit key with no passphrase:</p> <p> <code>ssh-keygen -t ecdsa -b 256 -N \"\" -m PEM -f my-new-server-key</code>.</p> <p>Valid values for the <code>-b</code> option for ECDSA are 256, 384, and 521.</p> <p>Use the following command to generate an ED25519 key with no passphrase:</p> <p> <code>ssh-keygen -t ed25519 -N \"\" -f my-new-server-key</code>.</p> <p>For all of these commands, you can replace <i>my-new-server-key</i> with a string of your choice.</p> <important> <p>If you aren't planning to migrate existing users from an existing SFTP-enabled server to a new server, don't update the host key. Accidentally changing a server's host key can be disruptive.</p> </important> <p>For more information, see <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/edit-server-config.html#configuring-servers-change-host-key\">Manage host keys for your SFTP-enabled server</a> in the <i>Transfer Family User Guide</i>.</p>"}))
    UpdateServerRequest.add_member(:identity_provider_details, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentityProviderDetails, location_name: 'IdentityProviderDetails', traits: {"smithy.api#documentation" => "<p>An array containing all of the information required to call a customer's authentication API method.</p>"}))
    UpdateServerRequest.add_member(:logging_role, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableRole, location_name: 'LoggingRole', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that allows a server to turn on Amazon CloudWatch logging for Amazon S3 or Amazon EFS events. When set, you can view user activity in your CloudWatch logs.</p>"}))
    UpdateServerRequest.add_member(:post_authentication_login_banner, Smithy::Schema::Shapes::ShapeRef.new(shape: PostAuthenticationLoginBanner, location_name: 'PostAuthenticationLoginBanner', traits: {"smithy.api#documentation" => "<p>Specifies a string to display when users connect to a server. This string is displayed after the user authenticates.</p> <note> <p>The SFTP protocol does not support post-authentication display banners.</p> </note>"}))
    UpdateServerRequest.add_member(:pre_authentication_login_banner, Smithy::Schema::Shapes::ShapeRef.new(shape: PreAuthenticationLoginBanner, location_name: 'PreAuthenticationLoginBanner', traits: {"smithy.api#documentation" => "<p>Specifies a string to display when users connect to a server. This string is displayed before the user authenticates. For example, the following banner displays details about using the system:</p> <p> <code>This system is for the use of authorized users only. Individuals using this computer system without authority, or in excess of their authority, are subject to having all of their activities on this system monitored and recorded by system personnel.</code> </p>"}))
    UpdateServerRequest.add_member(:protocols, Smithy::Schema::Shapes::ShapeRef.new(shape: Protocols, location_name: 'Protocols', traits: {"smithy.api#documentation" => "<p>Specifies the file transfer protocol or protocols over which your file transfer protocol client can connect to your server's endpoint. The available protocols are:</p> <ul> <li> <p> <code>SFTP</code> (Secure Shell (SSH) File Transfer Protocol): File transfer over SSH</p> </li> <li> <p> <code>FTPS</code> (File Transfer Protocol Secure): File transfer with TLS encryption</p> </li> <li> <p> <code>FTP</code> (File Transfer Protocol): Unencrypted file transfer</p> </li> <li> <p> <code>AS2</code> (Applicability Statement 2): used for transporting structured business-to-business data</p> </li> </ul> <note> <ul> <li> <p>If you select <code>FTPS</code>, you must choose a certificate stored in Certificate Manager (ACM) which is used to identify your server when clients connect to it over FTPS.</p> </li> <li> <p>If <code>Protocol</code> includes either <code>FTP</code> or <code>FTPS</code>, then the <code>EndpointType</code> must be <code>VPC</code> and the <code>IdentityProviderType</code> must be either <code>AWS_DIRECTORY_SERVICE</code>, <code>AWS_LAMBDA</code>, or <code>API_GATEWAY</code>.</p> </li> <li> <p>If <code>Protocol</code> includes <code>FTP</code>, then <code>AddressAllocationIds</code> cannot be associated.</p> </li> <li> <p>If <code>Protocol</code> is set only to <code>SFTP</code>, the <code>EndpointType</code> can be set to <code>PUBLIC</code> and the <code>IdentityProviderType</code> can be set any of the supported identity types: <code>SERVICE_MANAGED</code>, <code>AWS_DIRECTORY_SERVICE</code>, <code>AWS_LAMBDA</code>, or <code>API_GATEWAY</code>.</p> </li> <li> <p>If <code>Protocol</code> includes <code>AS2</code>, then the <code>EndpointType</code> must be <code>VPC</code>, and domain must be Amazon S3.</p> </li> </ul> </note>"}))
    UpdateServerRequest.add_member(:security_policy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityPolicyName, location_name: 'SecurityPolicyName', traits: {"smithy.api#documentation" => "<p>Specifies the name of the security policy for the server.</p>"}))
    UpdateServerRequest.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>A system-assigned unique identifier for a server instance that the Transfer Family user is assigned to.</p>", "smithy.api#required" => {}}))
    UpdateServerRequest.add_member(:workflow_details, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkflowDetails, location_name: 'WorkflowDetails', traits: {"smithy.api#documentation" => "<p>Specifies the workflow ID for the workflow to assign and the execution role that's used for executing the workflow.</p> <p>In addition to a workflow to execute when a file is uploaded completely, <code>WorkflowDetails</code> can also contain a workflow ID (and execution role) for a workflow to execute on partial upload. A partial upload occurs when the server session disconnects while the file is still being uploaded.</p> <p>To remove an associated workflow from a server, you can provide an empty <code>OnUpload</code> object, as in the following example.</p> <p> <code>aws transfer update-server --server-id s-01234567890abcdef --workflow-details '{\"OnUpload\":[]}'</code> </p>"}))
    UpdateServerRequest.add_member(:structured_log_destinations, Smithy::Schema::Shapes::ShapeRef.new(shape: StructuredLogDestinations, location_name: 'StructuredLogDestinations', traits: {"smithy.api#documentation" => "<p>Specifies the log groups to which your server logs are sent.</p> <p>To specify a log group, you must provide the ARN for an existing log group. In this case, the format of the log group is as follows:</p> <p> <code>arn:aws:logs:region-name:amazon-account-id:log-group:log-group-name:*</code> </p> <p>For example, <code>arn:aws:logs:us-east-1:111122223333:log-group:mytestgroup:*</code> </p> <p>If you have previously specified a log group for a server, you can clear it, and in effect turn off structured logging, by providing an empty value for this parameter in an <code>update-server</code> call. For example:</p> <p> <code>update-server --server-id s-1234567890abcdef0 --structured-log-destinations</code> </p>"}))
    UpdateServerRequest.add_member(:s3_storage_options, Smithy::Schema::Shapes::ShapeRef.new(shape: S3StorageOptions, location_name: 'S3StorageOptions', traits: {"smithy.api#documentation" => "<p>Specifies whether or not performance for your Amazon S3 directories is optimized. This is disabled by default.</p> <p>By default, home directory mappings have a <code>TYPE</code> of <code>DIRECTORY</code>. If you enable this option, you would then need to explicitly set the <code>HomeDirectoryMapEntry</code> <code>Type</code> to <code>FILE</code> if you want a mapping to have a file target.</p>"}))
    UpdateServerRequest.add_member(:ip_address_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddressType, location_name: 'IpAddressType', traits: {"smithy.api#documentation" => "<p>Specifies whether to use IPv4 only, or to use dual-stack (IPv4 and IPv6) for your Transfer Family endpoint. The default value is <code>IPV4</code>.</p> <important> <p>The <code>IpAddressType</code> parameter has the following limitations:</p> <ul> <li> <p>It cannot be changed while the server is online. You must stop the server before modifying this parameter.</p> </li> <li> <p>It cannot be updated to <code>DUALSTACK</code> if the server has <code>AddressAllocationIds</code> specified.</p> </li> </ul> </important> <note> <p>When using <code>DUALSTACK</code> as the <code>IpAddressType</code>, you cannot set the <code>AddressAllocationIds</code> parameter for the <a href=\"https://docs.aws.amazon.com/transfer/latest/APIReference/API_EndpointDetails.html\">EndpointDetails</a> for the server.</p> </note>"}))
    UpdateServerRequest.type = Types::UpdateServerRequest
    UpdateServerResponse.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>A system-assigned unique identifier for a server that the Transfer Family user is assigned to.</p>", "smithy.api#required" => {}}))
    UpdateServerResponse.type = Types::UpdateServerResponse
    UpdateUserRequest.add_member(:home_directory, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectory, location_name: 'HomeDirectory', traits: {"smithy.api#documentation" => "<p>The landing directory (folder) for a user when they log in to the server using the client.</p> <p>A <code>HomeDirectory</code> example is <code>/bucket_name/home/mydirectory</code>.</p> <note> <p>You can use the <code>HomeDirectory</code> parameter for <code>HomeDirectoryType</code> when it is set to either <code>PATH</code> or <code>LOGICAL</code>.</p> </note>"}))
    UpdateUserRequest.add_member(:home_directory_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryType, location_name: 'HomeDirectoryType', traits: {"smithy.api#documentation" => "<p>The type of landing directory (folder) that you want your users' home directory to be when they log in to the server. If you set it to <code>PATH</code>, the user will see the absolute Amazon S3 bucket or Amazon EFS path as is in their file transfer protocol clients. If you set it to <code>LOGICAL</code>, you need to provide mappings in the <code>HomeDirectoryMappings</code> for how you want to make Amazon S3 or Amazon EFS paths visible to your users.</p> <note> <p>If <code>HomeDirectoryType</code> is <code>LOGICAL</code>, you must provide mappings, using the <code>HomeDirectoryMappings</code> parameter. If, on the other hand, <code>HomeDirectoryType</code> is <code>PATH</code>, you provide an absolute path using the <code>HomeDirectory</code> parameter. You cannot have both <code>HomeDirectory</code> and <code>HomeDirectoryMappings</code> in your template.</p> </note>"}))
    UpdateUserRequest.add_member(:home_directory_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: HomeDirectoryMappings, location_name: 'HomeDirectoryMappings', traits: {"smithy.api#documentation" => "<p>Logical directory mappings that specify what Amazon S3 or Amazon EFS paths and keys should be visible to your user and how you want to make them visible. You must specify the <code>Entry</code> and <code>Target</code> pair, where <code>Entry</code> shows how the path is made visible and <code>Target</code> is the actual Amazon S3 or Amazon EFS path. If you only specify a target, it is displayed as is. You also must ensure that your Identity and Access Management (IAM) role provides access to paths in <code>Target</code>. This value can be set only when <code>HomeDirectoryType</code> is set to <i>LOGICAL</i>.</p> <p>The following is an <code>Entry</code> and <code>Target</code> pair example.</p> <p> <code>[ { \"Entry\": \"/directory1\", \"Target\": \"/bucket_name/home/mydirectory\" } ]</code> </p> <p>In most cases, you can use this value instead of the session policy to lock down your user to the designated home directory (\"<code>chroot</code>\"). To do this, you can set <code>Entry</code> to '/' and set <code>Target</code> to the HomeDirectory parameter value.</p> <p>The following is an <code>Entry</code> and <code>Target</code> pair example for <code>chroot</code>.</p> <p> <code>[ { \"Entry\": \"/\", \"Target\": \"/bucket_name/home/mydirectory\" } ]</code> </p>"}))
    UpdateUserRequest.add_member(:policy, Smithy::Schema::Shapes::ShapeRef.new(shape: Policy, location_name: 'Policy', traits: {"smithy.api#documentation" => "<p>A session policy for your user so that you can use the same Identity and Access Management (IAM) role across multiple users. This policy scopes down a user's access to portions of their Amazon S3 bucket. Variables that you can use inside this policy include <code>${Transfer:UserName}</code>, <code>${Transfer:HomeDirectory}</code>, and <code>${Transfer:HomeBucket}</code>.</p> <note> <p>This policy applies only when the domain of <code>ServerId</code> is Amazon S3. Amazon EFS does not use session policies.</p> <p>For session policies, Transfer Family stores the policy as a JSON blob, instead of the Amazon Resource Name (ARN) of the policy. You save the policy as a JSON blob and pass it in the <code>Policy</code> argument.</p> <p>For an example of a session policy, see <a href=\"https://docs.aws.amazon.com/transfer/latest/userguide/session-policy\">Creating a session policy</a>.</p> <p>For more information, see <a href=\"https://docs.aws.amazon.com/STS/latest/APIReference/API_AssumeRole.html\">AssumeRole</a> in the <i>Amazon Web Services Security Token Service API Reference</i>.</p> </note>"}))
    UpdateUserRequest.add_member(:posix_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: PosixProfile, location_name: 'PosixProfile', traits: {"smithy.api#documentation" => "<p>Specifies the full POSIX identity, including user ID (<code>Uid</code>), group ID (<code>Gid</code>), and any secondary groups IDs (<code>SecondaryGids</code>), that controls your users' access to your Amazon Elastic File Systems (Amazon EFS). The POSIX permissions that are set on files and directories in your file system determines the level of access your users get when transferring files into and out of your Amazon EFS file systems.</p>"}))
    UpdateUserRequest.add_member(:role, Smithy::Schema::Shapes::ShapeRef.new(shape: Role, location_name: 'Role', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Identity and Access Management (IAM) role that controls your users' access to your Amazon S3 bucket or Amazon EFS file system. The policies attached to this role determine the level of access that you want to provide your users when transferring files into and out of your Amazon S3 bucket or Amazon EFS file system. The IAM role should also contain a trust relationship that allows the server to access your resources when servicing your users' transfer requests.</p>"}))
    UpdateUserRequest.add_member(:server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerId, location_name: 'ServerId', traits: {"smithy.api#documentation" => "<p>A system-assigned unique identifier for a Transfer Family server instance that the user is assigned to.</p>", "smithy.api#required" => {}}))
    UpdateUserRequest.add_member(:user_name, Smithy::Schema::Shapes::ShapeRef.new(shape: UserName, location_name: 'UserName', traits: {"smithy.api#documentation" => "<p>A unique string that identifies a user and is associated with a server as specified by the <code>ServerId</code>. This user name must be a minimum of 3 and a maximum of 100 characters long. The following are valid characters: a-z, A-Z, 0-9, underscore '_', hyphen '-', period '.', and at sign '@'. The user name can't start with a hyphen, period, or at sign.</p>", "smithy.api#required" => {}}))
