    WorkflowStep.add_member(:custom_step_details, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomStepDetails, location_name: 'CustomStepDetails', traits: {"smithy.api#documentation" => "<p>Details for a step that invokes an Lambda function.</p> <p>Consists of the Lambda function's name, target, and timeout (in seconds). </p>"}))
